INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.TOTAL_VALUE_TENTH', 'MATH.G3.NUMBER.MULTIPLICATION.MULT_BY_10', 'skill', 'helpful', 'Multiplying by 10 is how a digit takes on the value of a higher place.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
