INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_TENTH.M_PV_GIVES_TOTAL_VALUE', 'MATH.G4.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_TENTH', 'Gives what the digit is worth when asked for its place.', '{"question":"In 45,362 what is the place value of 5?","wrong_answer":"5,000","correct_answer":"thousands"}'::jsonb, 'The terms place value and total value are used as the same thing.', 'Put the total value among the options as a distractor.', 'A place value chart with column names. Read the column name first, then say what the digit is worth.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_TENTH.M_PV_COUNT_FROM_LEFT', 'MATH.G4.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_TENTH', 'Counts the places from the left, so names the wrong place when numbers have different digit counts.', '{"question":"In 8,205 which place is the digit 2 in?","wrong_answer":"tens","correct_answer":"hundreds"}'::jsonb, 'Starts naming places at the first digit instead of at the ones.', 'Four-digit and five-digit numbers asked in the same session.', 'Always put the ones at the right end of the chart and name the columns from there.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_TENTH.M_PV_ZERO_IS_NOT_A_PLACE', 'MATH.G4.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_TENTH', 'Skips a zero when naming places, so the digits after it are named one place too high.', '{"question":"In 30,407 which place is the 4 in?","wrong_answer":"thousands","correct_answer":"hundreds"}'::jsonb, 'Treats zero as nothing instead of a place holder.', 'Numbers with a zero inside and a question about the digit after it.', 'Build 30,407 with place value cards: the zero card is a place too.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.TOTAL_VALUE_TENTH.M_TV_FACE_VALUE', 'MATH.G4.NUMBER.WHOLE_NUMBERS.TOTAL_VALUE_TENTH', 'Gives only the digit when asked what it is worth.', '{"question":"What is the total value of 7 in 27,540?","wrong_answer":"7","correct_answer":"7,000"}'::jsonb, 'Digit and total value are not told apart.', 'A total value question with the digit among the options.', 'Write the digit, then write a zero for every place to its right.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.TOTAL_VALUE_TENTH.M_TV_WRONG_ZEROS', 'MATH.G4.NUMBER.WHOLE_NUMBERS.TOTAL_VALUE_TENTH', 'Writes one zero too many or too few after the digit.', '{"question":"Total value of 3 in 83,214?","wrong_answer":"30,000","correct_answer":"3,000"}'::jsonb, 'Counts digits in the number instead of the places to the right of the digit.', 'Ten times and one tenth of the answer as options.', 'Count the digits to the right of the 3, then write that many zeros.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.TOTAL_VALUE_TENTH.M_TV_COMPOSE_DROPS_ZEROS', 'MATH.G4.NUMBER.WHOLE_NUMBERS.TOTAL_VALUE_TENTH', 'Writes a number from its total values by joining the non-zero digits and leaves out the empty places.', '{"question":"Write 40,000 + 600 + 8 as one number.","wrong_answer":"468","correct_answer":"40,608"}'::jsonb, 'Zero is not treated as a place holder.', 'Total values with one or two empty places.', 'Fill a five-column chart; write 0 in each empty column.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.SYMBOLS_10000.M_SYM_JOIN_PARTS', 'MATH.G4.NUMBER.WHOLE_NUMBERS.SYMBOLS_10000', 'Joins the parts as they are said and leaves out the zeros, so the number is too small.', '{"question":"Write four thousand and six in symbols.","wrong_answer":"46","correct_answer":"4,006"}'::jsonb, 'Writes each part with no place holder zero.', 'A number with an empty hundreds or tens place.', 'Write thousands, hundreds, tens and ones as four columns and fill every one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.SYMBOLS_10000.M_SYM_REVERSE_DIGITS', 'MATH.G4.NUMBER.WHOLE_NUMBERS.SYMBOLS_10000', 'Writes the digits in the order they are heard for the teens, as in fourteen written 41.', '{"question":"Write one thousand and fourteen in symbols.","wrong_answer":"1,041","correct_answer":"1,014"}'::jsonb, 'The ones of a teen word is heard first, so it is written first.', 'A number that ends in a teen.', 'Say the teen aloud and write the ten first: fourteen is 10 and 4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.SYMBOLS_10000.M_SYM_PARTS_WRITTEN_IN_FULL', 'MATH.G4.NUMBER.WHOLE_NUMBERS.SYMBOLS_10000', 'Writes each part in full with its zeros and joins them.', '{"question":"Write two thousand, three hundred and fifty in symbols.","wrong_answer":"2000300 50","correct_answer":"2,350"}'::jsonb, 'Writes 2,000 then 300 then 50 side by side, as the parts are said.', 'A number said in parts with a hundreds part and a tens part.', 'Check the answer has four digits: thousands, hundreds, tens and ones.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.WORDS_1000.M_WORDS_HUNDRED_DROPPED', 'MATH.G4.NUMBER.WHOLE_NUMBERS.WORDS_1000', 'Leaves out the word hundred, or the hundreds digit, when writing a number in words.', '{"question":"Write 405 in words.","wrong_answer":"forty-five","correct_answer":"four hundred and five"}'::jsonb, 'Reads the digits in pairs and treats zero as nothing.', 'A number with a zero in the tens place.', 'Cover the last two digits and say the hundreds first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.WORDS_1000.M_WORDS_SPELLING_TY', 'MATH.G4.NUMBER.WHOLE_NUMBERS.WORDS_1000', 'Mixes up -teen and -ty words, writing fourteen for forty or thirty for thirteen.', '{"question":"Write 340 in words.","wrong_answer":"three hundred and fourteen","correct_answer":"three hundred and forty"}'::jsonb, 'The words sound alike and the stress is on a different syllable.', 'Word choices with a teen and its -ty partner.', 'Say the word slowly: -teen is stressed, -ty is not. Link fourteen with 14 and forty with 40.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.WORDS_1000.M_WORDS_SPELLING_FORTY', 'MATH.G4.NUMBER.WHOLE_NUMBERS.WORDS_1000', 'Writes forty as fourty and ninety as ninty.', '{"question":"Choose the correct spelling of 49.","wrong_answer":"fourty-nine","correct_answer":"forty-nine"}'::jsonb, 'Spells forty like four.', 'Options that differ only in spelling.', 'Show that forty has no u, unlike four and fourteen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.ORDER_1000.M_ORDER_FIRST_DIGIT_ONLY', 'MATH.G4.NUMBER.WHOLE_NUMBERS.ORDER_1000', 'Orders numbers by their last digit or by the first digit only, ignoring how many digits there are.', '{"question":"Which is the largest of 98, 214 and 105?","wrong_answer":"98","correct_answer":"214"}'::jsonb, 'Compares one digit instead of counting the digits first.', 'A two-digit number with a bigger first digit than a three-digit number.', 'Count the digits first: more digits means a bigger number. Then compare the hundreds.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.ORDER_1000.M_ORDER_DIRECTION', 'MATH.G4.NUMBER.WHOLE_NUMBERS.ORDER_1000', 'Gives the order from largest to smallest when asked for smallest to largest, or the reverse.', '{"question":"Smallest to largest: 305, 350, 53","wrong_answer":"350, 305, 53","correct_answer":"53, 305, 350"}'::jsonb, 'Does not read the direction words.', 'The reversed list as an option.', 'Underline the direction words and write the first number you choose.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.ORDER_1000.M_ORDER_ZERO_TENS', 'MATH.G4.NUMBER.WHOLE_NUMBERS.ORDER_1000', 'Treats a number with a zero in the tens place as smaller than one with a tens digit, whatever the hundreds are.', '{"question":"Which is larger, 508 or 499?","wrong_answer":"499","correct_answer":"508"}'::jsonb, 'Reads the tens digit before the hundreds digit.', '508 against 499 style pairs.', 'Compare from the left: hundreds first. Stop as soon as the digits differ.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.ROUND_TEN_1000.M_ROUND_DROP_ONES', 'MATH.G4.NUMBER.WHOLE_NUMBERS.ROUND_TEN_1000', 'Drops the ones digit and never rounds up.', '{"question":"Round 468 to the nearest ten.","wrong_answer":"460","correct_answer":"470"}'::jsonb, 'Thinks rounding means cutting off the last digit.', 'Numbers whose ones digit is 5 or more.', 'Mark the two tens either side on a number line and see which is nearer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.ROUND_TEN_1000.M_ROUND_NO_CARRY', 'MATH.G4.NUMBER.WHOLE_NUMBERS.ROUND_TEN_1000', 'Rounds a number ending in 95 to 99 up to a ten but forgets to carry into the hundreds.', '{"question":"Round 396 to the nearest ten.","wrong_answer":"3100","correct_answer":"400"}'::jsonb, 'Writes 9 + 1 = 10 in the tens place without carrying.', 'Numbers just below a hundred, such as 397.', 'Count up to the next ten on the number line: 396, 397, 398, 399, 400.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.ROUND_TEN_1000.M_ROUND_WRONG_PLACE', 'MATH.G4.NUMBER.WHOLE_NUMBERS.ROUND_TEN_1000', 'Rounds to the nearest hundred when asked for the nearest ten.', '{"question":"Round 463 to the nearest ten.","wrong_answer":"500","correct_answer":"460"}'::jsonb, 'Does not read which place to round to.', 'A number whose nearest hundred is a close option.', 'Underline the place you are rounding to, then look at the digit next to it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.FACTORS_50.M_FACTOR_ONLY_ITSELF', 'MATH.G4.NUMBER.WHOLE_NUMBERS.FACTORS_50', 'Lists only the number itself or only the pairs that start with 2, leaving out 1 and the number.', '{"question":"List the factors of 12.","wrong_answer":"2, 3, 4, 6","correct_answer":"1, 2, 3, 4, 6, 12"}'::jsonb, 'Does not know that 1 and the number are always factors.', 'A list question where 1 and the number are the missing ones.', 'Write the factors in pairs: 1 x 12, 2 x 6, 3 x 4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.FACTORS_50.M_FACTOR_MULTIPLE_SWAP', 'MATH.G4.NUMBER.WHOLE_NUMBERS.FACTORS_50', 'Gives multiples when asked for factors.', '{"question":"List the factors of 6.","wrong_answer":"6, 12, 18, 24","correct_answer":"1, 2, 3, 6"}'::jsonb, 'Factor and multiple are not told apart.', 'A list of multiples among the options.', 'A factor divides into the number; a multiple is in its times table.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.FACTORS_50.M_FACTOR_MISSED_PAIR', 'MATH.G4.NUMBER.WHOLE_NUMBERS.FACTORS_50', 'Stops the list early and misses a factor pair.', '{"question":"List the factors of 36.","wrong_answer":"1, 2, 3, 4, 6, 9, 36","correct_answer":"1, 2, 3, 4, 6, 9, 12, 18, 36"}'::jsonb, 'Stops once the halfway number is passed.', 'Numbers up to 50 with several pairs.', 'Test every number from 1 up to the number; stop when the pairs meet.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.MULTIPLES_100.M_MULTIPLE_FACTOR_SWAP', 'MATH.G4.NUMBER.WHOLE_NUMBERS.MULTIPLES_100', 'Gives factors when asked for multiples.', '{"question":"Write the first four multiples of 5.","wrong_answer":"1, 5","correct_answer":"5, 10, 15, 20"}'::jsonb, 'Confuses the two words.', 'Factors among the options.', 'Multiples are the numbers you say when you count in fives.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.MULTIPLES_100.M_MULTIPLE_STARTS_AT_ZERO_OR_ONE', 'MATH.G4.NUMBER.WHOLE_NUMBERS.MULTIPLES_100', 'Starts the list at the number plus one, so the number itself is left out, or counts in ones.', '{"question":"First three multiples of 7.","wrong_answer":"8, 9, 10","correct_answer":"7, 14, 21"}'::jsonb, 'Counts on from the number instead of adding the number each time.', 'A list question for multiples of 7 or 9.', 'Skip count: say 7, then add 7 each time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.MULTIPLES_100.M_MULTIPLE_NOT_CHECKED', 'MATH.G4.NUMBER.WHOLE_NUMBERS.MULTIPLES_100', 'Calls a number a multiple because it is bigger than the number.', '{"question":"Is 25 a multiple of 4?","wrong_answer":"Yes, it is bigger than 4","correct_answer":"No, 4 x 6 = 24 and 4 x 7 = 28"}'::jsonb, 'Thinks any larger number is a multiple.', 'A yes or no question with a close number.', 'Skip count in fours and see whether 25 is said.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.EVEN_ODD_100.M_EVEN_ODD_TENS_DIGIT', 'MATH.G4.NUMBER.WHOLE_NUMBERS.EVEN_ODD_100', 'Decides even or odd from the tens digit instead of the ones digit.', '{"question":"Is 47 even or odd?","wrong_answer":"even","correct_answer":"odd"}'::jsonb, 'Looks at the first digit because it is read first.', 'Numbers whose tens and ones digits differ in kind, such as 47 and 52.', 'Only the digit in the ones place matters.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.EVEN_ODD_100.M_ZERO_NOT_EVEN', 'MATH.G4.NUMBER.WHOLE_NUMBERS.EVEN_ODD_100', 'Says a number ending in zero is odd or neither.', '{"question":"Is 30 even or odd?","wrong_answer":"odd","correct_answer":"even"}'::jsonb, 'Treats zero as nothing, not as an even digit.', 'Multiples of ten in a list.', 'Share 30 into two equal groups: nothing is left over.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.EVEN_ODD_100.M_EVEN_MEANS_BIG', 'MATH.G4.NUMBER.WHOLE_NUMBERS.EVEN_ODD_100', 'Thinks even means a large number, or odd means a strange number, and does not use the test.', '{"question":"Which is odd: 40, 66, 73 or 88?","wrong_answer":"40","correct_answer":"73"}'::jsonb, 'Even and odd are guessed from how a number looks.', 'A list of numbers with a single odd one.', 'Share each number into two equal groups and see what is left.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.EVEN_ODD_PATTERNS.M_PATTERN_ADD_ONE', 'MATH.G4.NUMBER.WHOLE_NUMBERS.EVEN_ODD_PATTERNS', 'Continues an even-number pattern by adding 1, so odd numbers appear.', '{"question":"Next in 12, 14, 16, ?","wrong_answer":"17","correct_answer":"18"}'::jsonb, 'Sees the numbers as a count, not a step of 2.', 'Even patterns written without a rule.', 'Say the difference between two numbers next to each other and use it again.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.EVEN_ODD_PATTERNS.M_PATTERN_WRONG_PARITY', 'MATH.G4.NUMBER.WHOLE_NUMBERS.EVEN_ODD_PATTERNS', 'Gives a missing term of the wrong kind, an even number in an odd pattern.', '{"question":"Missing term in 31, 33, ?, 37.","wrong_answer":"34","correct_answer":"35"}'::jsonb, 'Does not check the step between terms.', 'A missing term with a close even number as an option.', 'Check that the step from term to term is the same each time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.EVEN_ODD_PATTERNS.M_PATTERN_HOUSES_ONE_SIDE', 'MATH.G4.NUMBER.WHOLE_NUMBERS.EVEN_ODD_PATTERNS', 'Counts all house numbers in a street as consecutive, not one side evens and the other odds.', '{"question":"Houses on the left side of a road are 2, 4, 6. What is the next house?","wrong_answer":"7","correct_answer":"8"}'::jsonb, 'Does not connect the pattern to the real street.', 'A story about one side of a road.', 'Read the first three numbers and say what is the same about them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.ROMAN_TO_X.M_ROMAN_IV_AS_6', 'MATH.G4.NUMBER.WHOLE_NUMBERS.ROMAN_TO_X', 'Reads IV as 6 (I after V) or as 6 because both letters are present.', '{"question":"What number is IV?","wrong_answer":"6","correct_answer":"4"}'::jsonb, 'Adds the letters from left to right.', 'IV and IX read as numbers.', 'A smaller numeral before a larger one is taken away: 5 take away 1.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.ROMAN_TO_X.M_ROMAN_IIII_FOR_4', 'MATH.G4.NUMBER.WHOLE_NUMBERS.ROMAN_TO_X', 'Writes four as IIII, because three is III.', '{"question":"Write 4 in Roman numerals.","wrong_answer":"IIII","correct_answer":"IV"}'::jsonb, 'Continues the pattern of adding I.', 'A number to Roman choice question with IIII.', 'Use V for five and take one away.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.ROMAN_TO_X.M_ROMAN_X_AS_5', 'MATH.G4.NUMBER.WHOLE_NUMBERS.ROMAN_TO_X', 'Mixes the symbols V and X.', '{"question":"Write 10 in Roman numerals.","wrong_answer":"V","correct_answer":"X"}'::jsonb, 'The two symbols are learned together and swapped.', 'A matching question with V and X.', 'Roman clock face: V is at the 5 and X is at the 10.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_TENTH.M_PV_TEN_THOUSANDS_AS_THOUSANDS', 'MATH.G4.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_TENTH', 'Calls the fifth place from the right thousands, not ten thousands.', '{"question":"In 62,418 which place is the 6 in?","wrong_answer":"thousands","correct_answer":"ten thousands"}'::jsonb, 'Grade 3 stopped at hundreds and the child knows only one name past it.', 'The answer thousands as a wrong option, with a reason that names the idea.', 'A five-column chart with the heading Ten thousands written in full.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.TOTAL_VALUE_TENTH.M_TV_WHOLE_NUMBER_GIVEN', 'MATH.G4.NUMBER.WHOLE_NUMBERS.TOTAL_VALUE_TENTH', 'Gives the whole number when asked for the total value of one digit.', '{"question":"What is the total value of 4 in 3,482?","wrong_answer":"3,482","correct_answer":"400"}'::jsonb, 'Hears "value" and gives the value of the number.', 'The answer 3,482 as a wrong option, with a reason that names the idea.', 'Cover every digit except the one asked about, then fill the places to its right with zeros.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.SYMBOLS_10000.M_SYM_PART_SHIFTED', 'MATH.G4.NUMBER.WHOLE_NUMBERS.SYMBOLS_10000', 'Writes the tens-and-ones part one place too far left, so the ones place is left empty and filled with zero.', '{"question":"Write three thousand and forty-five in symbols.","wrong_answer":"3,450","correct_answer":"3,045"}'::jsonb, 'Writes 45 straight after the thousands digit and adds a zero to make four digits.', 'The answer 3,450 as a wrong option, with a reason that names the idea.', 'Say the places: 3 thousands, 0 hundreds, 4 tens, 5 ones. Write one digit under each heading.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.WORDS_1000.M_WORDS_TEEN_AS_TEN_AND', 'MATH.G4.NUMBER.WHOLE_NUMBERS.WORDS_1000', 'Writes a teen number as ten and its ones, the way it is said in Kiswahili (kumi na tano).', '{"question":"Write 615 in words.","wrong_answer":"six hundred and ten five","correct_answer":"six hundred and fifteen"}'::jsonb, 'Builds the English word from the Kiswahili pattern: ten and five.', 'The answer six hundred and ten five as a wrong option, with a reason that names the idea.', 'Make a teen card set: 13 thirteen, 14 fourteen, 15 fifteen. Say each one as one word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.ORDER_1000.M_ORDER_TABLE_POSITION', 'MATH.G4.NUMBER.WHOLE_NUMBERS.ORDER_1000', 'Takes the numbers in the order they are listed instead of putting them in order first.', '{"question":"Which is the third smallest: 450, 312, 789, 501?","wrong_answer":"789","correct_answer":"501"}'::jsonb, 'Counts down the list as it is written.', 'The answer 789 as a wrong option, with a reason that names the idea.', 'Write the numbers again from smallest to largest, then count.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.ROUND_TEN_1000.M_ROUND_FIVE_DOWN', 'MATH.G4.NUMBER.WHOLE_NUMBERS.ROUND_TEN_1000', 'Rounds a number that ends in 5 down, because 5 is exactly halfway.', '{"question":"Round 345 to the nearest ten.","wrong_answer":"340","correct_answer":"350"}'::jsonb, 'Does not know the rule for the halfway number.', 'The answer 340 as a wrong option, with a reason that names the idea.', 'On the number line 345 is exactly halfway; the rule is that 5 rounds up.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.FACTORS_50.M_FACTOR_NOT_TESTED', 'MATH.G4.NUMBER.WHOLE_NUMBERS.FACTORS_50', 'Decides whether a number is a factor from its look or size, without dividing.', '{"question":"Is 7 a factor of 42?","wrong_answer":"No, 7 is odd and 42 is even","correct_answer":"Yes: 42 ÷ 7 = 6"}'::jsonb, 'Uses a feeling about the numbers instead of a test.', 'The answer No, 7 is odd and 42 is even as a wrong option, with a reason that names the idea.', 'Always test: divide, and see if anything is left over.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.MULTIPLES_100.M_MULTIPLE_ANY_EVEN', 'MATH.G4.NUMBER.WHOLE_NUMBERS.MULTIPLES_100', 'Thinks an even number is a multiple of every even number.', '{"question":"Is 14 a multiple of 4?","wrong_answer":"Yes, both are even","correct_answer":"No: 4 x 3 = 12 and 4 x 4 = 16"}'::jsonb, 'Mixes up "even" (a multiple of 2) with "a multiple of this number".', 'The answer Yes, both are even as a wrong option, with a reason that names the idea.', 'Count in fours on a number line and see that 14 is not landed on.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.EVEN_ODD_100.M_ODD_PLUS_ODD_ODD', 'MATH.G4.NUMBER.WHOLE_NUMBERS.EVEN_ODD_100', 'Thinks adding two odd numbers gives an odd number.', '{"question":"Is 27 + 15 even or odd?","wrong_answer":"odd","correct_answer":"even: 42"}'::jsonb, 'Expects the answer to be the same kind as the numbers added.', 'The answer odd as a wrong option, with a reason that names the idea.', 'Pair up counters: the two odd ones left over make a new pair.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.EVEN_ODD_100.M_EVEN_PAIRS_COUNTED', 'MATH.G4.NUMBER.WHOLE_NUMBERS.EVEN_ODD_100', 'Counts the pairs and calls the number even without checking for one left over.', '{"question":"17 learners stand in pairs. Is 17 even or odd?","wrong_answer":"even, there are 8 pairs","correct_answer":"odd: 1 learner has no partner"}'::jsonb, 'Looks at the pairs made, not at what is left.', 'The answer even, there are 8 pairs as a wrong option, with a reason that names the idea.', 'Ask: is anyone left without a partner? If yes, the number is odd.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.EVEN_ODD_PATTERNS.M_PATTERN_ADDING_CHANGES_PARITY', 'MATH.G4.NUMBER.WHOLE_NUMBERS.EVEN_ODD_PATTERNS', 'Thinks adding an even step turns odd numbers into even ones.', '{"question":"5, 9, 13 goes up by 4. Is the next number even or odd?","wrong_answer":"even","correct_answer":"odd: 17"}'::jsonb, 'Expects a pattern of odd and even to swap when it moves on.', 'The answer even as a wrong option, with a reason that names the idea.', 'Add 4 to an odd number on counters: the one left over is still there.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.ROMAN_TO_X.M_ROMAN_CLOCK_NUMBER_AS_MINUTES', 'MATH.G4.NUMBER.WHOLE_NUMBERS.ROMAN_TO_X', 'Reads the Roman numeral the minute hand points to as the minutes.', '{"question":"On a clock with Roman numerals the minute hand points to III. How many minutes past the hour?","wrong_answer":"3","correct_answer":"15"}'::jsonb, 'Reads the numeral as a number without the 5 minutes each mark stands for.', 'The answer 3 as a wrong option, with a reason that names the idea.', 'Count in fives round the clock face: I is 5 minutes, II is 10, III is 15.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.WHOLE_NUMBERS.ROMAN_TO_X.M_ROMAN_IX_AS_11', 'MATH.G4.NUMBER.WHOLE_NUMBERS.ROMAN_TO_X', 'Reads IX as 11, adding the I instead of taking it away.', '{"question":"What number is IX?","wrong_answer":"11","correct_answer":"9"}'::jsonb, 'Adds every numeral, whatever its position.', 'The answer 11 as a wrong option, with a reason that names the idea.', 'A small numeral before a bigger one is taken away: IX is one before ten.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.ADDITION.ADD_SINGLE_REGROUP.M_ADD_NO_CARRY', 'MATH.G4.NUMBER.ADDITION.ADD_SINGLE_REGROUP', 'Writes the full two-digit total in one column and does not carry.', '{"question":"2,468 + 1,359","wrong_answer":"371117","correct_answer":"3,827"}'::jsonb, 'Writes 8 + 9 = 17 in the ones column.', 'A column addition where one place total is above 9.', 'Write only the ones digit and carry the ten to the tens column; use place value blocks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.ADDITION.ADD_SINGLE_REGROUP.M_ADD_CARRY_FORGOTTEN', 'MATH.G4.NUMBER.ADDITION.ADD_SINGLE_REGROUP', 'Carries the ten but does not add it in the next column.', '{"question":"3,846 + 2,175","wrong_answer":"5,911","correct_answer":"6,021"}'::jsonb, 'Writes the carry above the column then forgets it.', 'A carry above the tens column.', 'Say the carry out loud as you add it: 4 plus 7 plus 1 carried.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.ADDITION.ADD_SINGLE_REGROUP.M_ADD_COLUMNS_MISALIGNED', 'MATH.G4.NUMBER.ADDITION.ADD_SINGLE_REGROUP', 'Lines up the numbers from the left, so ones are added to tens.', '{"question":"3,456 + 78","wrong_answer":"4,236","correct_answer":"3,534"}'::jsonb, 'Aligns from the left, as in writing words.', 'Numbers with a different count of digits.', 'Always put the ones at the right edge and rule the columns.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.ADDITION.ADD_DOUBLE_REGROUP.M_ADD_CARRY_ONLY_ONCE', 'MATH.G4.NUMBER.ADDITION.ADD_DOUBLE_REGROUP', 'Carries once and forgets the carry from the tens column.', '{"question":"2,785 + 1,468","wrong_answer":"4,153","correct_answer":"4,253"}'::jsonb, 'Carries out of the ones and then stops carrying.', 'Two carrying columns in the same sum.', 'Carry after each column, write one digit under the line.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.ADDITION.ADD_DOUBLE_REGROUP.M_ADD_THOUSANDS_DROPPED', 'MATH.G4.NUMBER.ADDITION.ADD_DOUBLE_REGROUP', 'Forgets that a carry out of the hundreds makes a thousand and writes only three digits in the answer.', '{"question":"5,678 + 4,837","wrong_answer":"515","correct_answer":"10,515"}'::jsonb, 'Stops when the columns end.', 'A sum with a carry past the thousands that reaches 10,000.', 'Write the carry as the next digit on the left.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.ADDITION.ESTIMATE_SUM_TEN.M_EST_ROUND_ONLY_ONE', 'MATH.G4.NUMBER.ADDITION.ESTIMATE_SUM_TEN', 'Rounds one number and adds the other as it is.', '{"question":"Estimate 347 + 582.","wrong_answer":"932","correct_answer":"930"}'::jsonb, 'Does not see that both numbers are rounded.', 'An estimate asked for with two close numbers.', 'Round both numbers first, then add.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.ADDITION.ESTIMATE_SUM_TEN.M_EST_ROUND_WRONG', 'MATH.G4.NUMBER.ADDITION.ESTIMATE_SUM_TEN', 'Rounds down every number to the ten below.', '{"question":"Estimate 68 + 47.","wrong_answer":"100","correct_answer":"120"}'::jsonb, 'Thinks rounding is cutting the ones off.', 'Numbers with ones digits of 5 and more.', 'Mark each number on a number line between two tens.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.ADDITION.ESTIMATE_SUM_TEN.M_EST_EXACT_REQUIRED', 'MATH.G4.NUMBER.ADDITION.ESTIMATE_SUM_TEN', 'Works out the exact sum when asked to estimate and calls it the estimate.', '{"question":"Estimate 348 + 267 by rounding to the nearest ten.","wrong_answer":"615","correct_answer":"620"}'::jsonb, 'Does not see the difference between estimating and working out.', 'An estimate that differs from the exact answer.', 'Ask: what are the rounded numbers? Write them first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.ADDITION.ADD_PATTERNS.M_PAT_ADD_ONE_STEP_ONLY', 'MATH.G4.NUMBER.ADDITION.ADD_PATTERNS', 'Uses the difference between the first two terms only and gets later terms wrong when the step changes.', '{"question":"Next term: 1,200, 1,500, 1,800, ?","wrong_answer":"1,900","correct_answer":"2,100"}'::jsonb, 'Applies the last digit change and not the whole step.', 'A pattern with a step of 300 or 250.', 'Subtract term from term to find the step, then use it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.ADDITION.ADD_PATTERNS.M_PAT_RULE_AS_TERM', 'MATH.G4.NUMBER.ADDITION.ADD_PATTERNS', 'Gives the next term when asked for the rule, or the rule when asked for the term.', '{"question":"What is the rule for 2,000, 2,500, 3,000?","wrong_answer":"3,500","correct_answer":"add 500"}'::jsonb, 'Does not read the question word.', 'A question that asks for the rule.', 'Underline what is asked: the rule or the number.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.ADDITION.ADD_PATTERNS.M_PAT_MISSING_NOT_CHECKED', 'MATH.G4.NUMBER.ADDITION.ADD_PATTERNS', 'Finds a missing term by guessing and does not check the step on both sides.', '{"question":"Missing term: 3,100, ?, 3,700, 4,000","wrong_answer":"3,500","correct_answer":"3,400"}'::jsonb, 'Does not use the step between known terms.', 'A pattern with the gap in the middle.', 'Find the step from the two known terms either side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.ADDITION.ADD_SINGLE_REGROUP.M_ADD_CARRY_WRONG_COLUMN', 'MATH.G4.NUMBER.ADDITION.ADD_SINGLE_REGROUP', 'Adds the carried 1 to a column further left, not to the next one.', '{"question":"1,456 + 2,327","wrong_answer":"3,873","correct_answer":"3,783"}'::jsonb, 'Writes the small 1 above the wrong column.', 'The answer 3,873 as a wrong option, with a reason that names the idea.', 'Write the carried 1 at the top of the very next column as soon as you carry it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.ADDITION.ADD_DOUBLE_REGROUP.M_ADD_TENS_DIGIT_WRITTEN', 'MATH.G4.NUMBER.ADDITION.ADD_DOUBLE_REGROUP', 'Writes the tens digit of a column sum and carries the ones digit.', '{"question":"2,785 + 1,468","wrong_answer":"11,111","correct_answer":"4,253"}'::jsonb, 'Does not know which digit of 13 stays and which is carried.', 'The answer 11,111 as a wrong option, with a reason that names the idea.', 'With bundles of ten: 13 ones is 1 ten and 3 ones. The 3 stays; the ten moves left.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.ADDITION.ADD_DOUBLE_REGROUP.M_ADD_CARRIES_EVERY_COLUMN', 'MATH.G4.NUMBER.ADDITION.ADD_DOUBLE_REGROUP', 'Once regrouping has started, carries 1 into every column, even when a column adds to less than 10.', '{"question":"3,658 + 2,147","wrong_answer":"6,805","correct_answer":"5,805"}'::jsonb, 'Learns carrying as a step to do every time, not as a result of 10 or more.', 'The answer 6,805 as a wrong option, with a reason that names the idea.', 'Before carrying, ask: is this column 10 or more?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.ADDITION.ESTIMATE_SUM_TEN.M_EST_ROUND_TO_HUNDRED', 'MATH.G4.NUMBER.ADDITION.ESTIMATE_SUM_TEN', 'Rounds to the nearest hundred when the nearest ten is asked.', '{"question":"Estimate 347 + 582 by rounding to the nearest ten.","wrong_answer":"900","correct_answer":"930"}'::jsonb, 'Rounds as far as possible to make it easy.', 'The answer 900 as a wrong option, with a reason that names the idea.', 'Underline the tens digit: that is the place you round to.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.ADDITION.ADD_PATTERNS.M_PAT_DOUBLES', 'MATH.G4.NUMBER.ADDITION.ADD_PATTERNS', 'Doubles the last term instead of adding the same step.', '{"question":"Next: 1,250, 1,500, 1,750, ?","wrong_answer":"3,500","correct_answer":"2,000"}'::jsonb, 'Sees the numbers grow and multiplies.', 'The answer 3,500 as a wrong option, with a reason that names the idea.', 'Write the jump between each pair of terms under the pattern.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.SUBTRACTION.SUB_NO_REGROUP.M_SUB_ZERO_RESULT_DROPPED', 'MATH.G4.NUMBER.SUBTRACTION.SUB_NO_REGROUP', 'Leaves out a zero in the answer when a column has nothing left.', '{"question":"5,420 - 2,310","wrong_answer":"311","correct_answer":"3,110"}'::jsonb, 'Does not write 0 for a place with nothing left.', 'A subtraction with a zero in the answer.', 'Check the answer has four digits.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.SUBTRACTION.SUB_NO_REGROUP.M_SUB_ADDS', 'MATH.G4.NUMBER.SUBTRACTION.SUB_NO_REGROUP', 'Adds when the story says how many are left.', '{"question":"A farmer had 4,800 eggs and sold 2,300. How many are left?","wrong_answer":"7,100","correct_answer":"2,500"}'::jsonb, 'Looks at the numbers, not at what is asked.', 'A take-away story with an operation word like left.', 'Draw the whole and the part that went away.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.SUBTRACTION.SUB_NO_REGROUP.M_SUB_COLUMNS_MISALIGNED', 'MATH.G4.NUMBER.SUBTRACTION.SUB_NO_REGROUP', 'Lines the numbers up from the left.', '{"question":"4,567 - 123","wrong_answer":"3,337","correct_answer":"4,444"}'::jsonb, 'Starts the subtraction from the left side of the page.', 'Numbers with different digit counts.', 'Rule the columns and write the ones at the right edge.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.SUBTRACTION.SUB_REGROUP.M_SUB_SMALLER_FROM_LARGER', 'MATH.G4.NUMBER.SUBTRACTION.SUB_REGROUP', 'Takes the smaller digit from the larger in each column instead of regrouping.', '{"question":"6,304 - 2,578","wrong_answer":"4,274","correct_answer":"3,726"}'::jsonb, 'Does not know to borrow from the next place.', 'A subtraction where each column needs regrouping.', 'Use place value blocks: you cannot take 8 from 4, so exchange a ten.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.SUBTRACTION.SUB_REGROUP.M_SUB_BORROW_NOT_REDUCED', 'MATH.G4.NUMBER.SUBTRACTION.SUB_REGROUP', 'Adds ten to the ones but does not reduce the next digit by one.', '{"question":"4,230 - 1,845","wrong_answer":"3,495","correct_answer":"2,385"}'::jsonb, 'Borrows but forgets to cross out the digit lent.', 'A regrouping subtraction that shows a lent digit.', 'Cross out the digit and write the new number above it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.SUBTRACTION.SUB_REGROUP.M_SUB_ZERO_REGROUP', 'MATH.G4.NUMBER.SUBTRACTION.SUB_REGROUP', 'Cannot regroup across a zero and writes 0 - 1 = 1 or 9 out of order.', '{"question":"4,005 - 1,278","wrong_answer":"3,273","correct_answer":"2,727"}'::jsonb, 'Does not know to go to the next non-zero digit.', 'A minuend with a zero in the tens and hundreds place.', 'Exchange one thousand for ten hundreds, one hundred for ten tens, then a ten for ten ones.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
