INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.MULTIPLICATION.MULT_2D_REGROUP.M_MUL_CARRY_FORGOTTEN', 'MATH.G4.NUMBER.MULTIPLICATION.MULT_2D_REGROUP', 'Forgets the carried digit when adding it to the next product.', '{"question":"What is 36 x 24?","wrong_answer":"744","correct_answer":"864"}'::jsonb, 'Writes the carry then drops it.', 'A working with a carry written above the column.', 'Say the carry out loud: 6 x 4 = 24, write 4, carry 2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
