INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.MULTIPLICATION.MULT_PATTERNS.M_MULPAT_ADD_STEP', 'MATH.G4.NUMBER.MULTIPLICATION.MULT_PATTERNS', 'Uses adding the last step as the rule for a multiplication pattern.', '{"question":"Next: 3, 6, 12, 24, ?","wrong_answer":"27","correct_answer":"48"}'::jsonb, 'Sees the first step as the rule.', 'A doubling pattern.', 'Find what each term is multiplied by to give the next.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.MULTIPLICATION.MULT_PATTERNS.M_MULPAT_SKIP_TABLE', 'MATH.G4.NUMBER.MULTIPLICATION.MULT_PATTERNS', 'Skips a term in a times-table pattern.', '{"question":"Next: 8, 16, 24, ?","wrong_answer":"40","correct_answer":"32"}'::jsonb, 'Loses count of the table.', 'A table pattern with a gap.', 'Say the table from the start.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.MULTIPLICATION.MULT_PATTERNS.M_MULPAT_RULE_AS_TERM', 'MATH.G4.NUMBER.MULTIPLICATION.MULT_PATTERNS', 'Gives the next term when asked for the rule.', '{"question":"What is the rule for 5, 10, 20, 40?","wrong_answer":"80","correct_answer":"multiply by 2"}'::jsonb, 'Does not read what is asked.', 'A rule question.', 'Underline what is asked.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.MULTIPLICATION.MULT_BY_TENS.M_MUL_TENS_ZERO_IN_MIDDLE', 'MATH.G4.NUMBER.MULTIPLICATION.MULT_BY_TENS', 'Puts the zero between the digits instead of at the end.', '{"question":"What is 23 x 10?","wrong_answer":"203","correct_answer":"230"}'::jsonb, 'Knows a zero is added but not where it goes.', 'The answer 203 as a wrong option, with a reason that names the idea.', 'Each digit moves one place left; the empty ones place gets the zero.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.MULTIPLICATION.MULT_2D_NO_REGROUP.M_MUL_BY_ONES_DIGIT_ONLY', 'MATH.G4.NUMBER.MULTIPLICATION.MULT_2D_NO_REGROUP', 'Multiplies by the ones digit only and forgets the tens of the second number.', '{"question":"What is 12 x 13?","wrong_answer":"36","correct_answer":"156"}'::jsonb, 'Stops after the first row of the long multiplication.', 'The answer 36 as a wrong option, with a reason that names the idea.', 'Split 13 into 10 and 3: 12 x 10 and 12 x 3, then add.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.MULTIPLICATION.MULT_2D_REGROUP.M_MUL_PRODUCTS_WRITTEN_SIDE_BY_SIDE', 'MATH.G4.NUMBER.MULTIPLICATION.MULT_2D_REGROUP', 'Writes each digit''s full product side by side instead of carrying.', '{"question":"What is 36 x 4?","wrong_answer":"1224","correct_answer":"144"}'::jsonb, 'Writes 24 and then 12 without regrouping the tens.', 'The answer 1224 as a wrong option, with a reason that names the idea.', 'Write the 4 ones, carry the 2 tens, add it to 3 x 4 = 12 tens.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.MULTIPLICATION.ESTIMATE_PRODUCT_TEN.M_EST_PROD_ADDED', 'MATH.G4.NUMBER.MULTIPLICATION.ESTIMATE_PRODUCT_TEN', 'Rounds both numbers and then adds them.', '{"question":"Estimate 38 x 21.","wrong_answer":"60","correct_answer":"800"}'::jsonb, 'Rounds correctly but uses the wrong operation.', 'The answer 60 as a wrong option, with a reason that names the idea.', 'An estimate of a product is still a multiplication: 40 x 20.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.MULTIPLICATION.MULT_PATTERNS.M_MULPAT_MISSING_AS_MIDDLE', 'MATH.G4.NUMBER.MULTIPLICATION.MULT_PATTERNS', 'Fills a gap with the number halfway between its neighbours, as if the pattern added.', '{"question":"Missing: 4, ?, 16, 32","wrong_answer":"10","correct_answer":"8"}'::jsonb, 'Treats the gap as an addition pattern.', 'The answer 10 as a wrong option, with a reason that names the idea.', 'Find the rule from two terms side by side: 16 x 2 = 32, so 4 x 2 = 8.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.DIVISION.DIV_NO_REMAINDER.M_DIV_LARGER_BY_SMALLER', 'MATH.G4.NUMBER.DIVISION.DIV_NO_REMAINDER', 'Divides the larger digit by the smaller one, whichever way round.', '{"question":"What is 72 divided by 6?","wrong_answer":"13","correct_answer":"12"}'::jsonb, 'Does 6 divided by 2 for the ones because it divides exactly.', 'A dividend whose ones digit is not a multiple of the divisor.', 'Share the tens first, then exchange what is left for ones.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.DIVISION.DIV_NO_REMAINDER.M_DIV_ZERO_DROPPED', 'MATH.G4.NUMBER.DIVISION.DIV_NO_REMAINDER', 'Leaves out the zero in the answer when a place gets nothing.', '{"question":"What is 60 divided by 3?","wrong_answer":"2","correct_answer":"20"}'::jsonb, 'Does not write 0 when 3 does not go into the ones.', 'A dividend like 60 or 80.', 'Check by multiplying 2 x 3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.DIVISION.DIV_NO_REMAINDER.M_DIV_SUBTRACT', 'MATH.G4.NUMBER.DIVISION.DIV_NO_REMAINDER', 'Subtracts instead of dividing.', '{"question":"Share 36 oranges among 4 children equally.","wrong_answer":"32","correct_answer":"9"}'::jsonb, 'Reads share as take away.', 'A sharing story.', 'Draw 4 groups and put one orange at a time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.DIVISION.DIV_WITH_REMAINDER.M_DIV_REMAINDER_TOO_BIG', 'MATH.G4.NUMBER.DIVISION.DIV_WITH_REMAINDER', 'Writes a remainder as big as or bigger than the divisor.', '{"question":"47 divided by 5","wrong_answer":"8 remainder 7","correct_answer":"9 remainder 2"}'::jsonb, 'Stops dividing too early.', 'A remainder bigger than the divisor as an option.', 'After dividing, the remainder must be smaller than what you divide by.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.DIVISION.DIV_WITH_REMAINDER.M_DIV_REMAINDER_IGNORED', 'MATH.G4.NUMBER.DIVISION.DIV_WITH_REMAINDER', 'Gives the quotient only and drops the remainder.', '{"question":"23 divided by 4","wrong_answer":"5","correct_answer":"5 remainder 3"}'::jsonb, 'Thinks the remainder is not part of the answer.', 'A division that does not go exactly.', 'Multiply the quotient by the divisor: does it get back to 23?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.DIVISION.DIV_WITH_REMAINDER.M_DIV_REMAINDER_AS_ANSWER', 'MATH.G4.NUMBER.DIVISION.DIV_WITH_REMAINDER', 'Gives the remainder alone as the answer.', '{"question":"How many full packets of 6 can be made from 40 eggs?","wrong_answer":"4","correct_answer":"6"}'::jsonb, 'Reads the leftover as the answer.', 'A story that asks how many full groups.', 'Ask what the question needs: groups or leftovers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.DIVISION.DIV_WITH_REMAINDER.M_DIV_STORY_REMAINDER_DOWN', 'MATH.G4.NUMBER.DIVISION.DIV_WITH_REMAINDER', 'Rounds down when the story needs one more (a bus for the leftover children).', '{"question":"47 children go on a trip in buses of 10. How many buses are needed?","wrong_answer":"4","correct_answer":"5"}'::jsonb, 'Ignores the leftover children.', 'A story where the remainder needs one more.', 'Ask what happens to the leftover children.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.DIVISION.MULT_DIV_RELATE.M_RELATE_WRONG_FACT', 'MATH.G4.NUMBER.DIVISION.MULT_DIV_RELATE', 'Writes a division fact with the wrong numbers as the related fact.', '{"question":"6 x 7 = 42. Which division fact goes with it?","wrong_answer":"6 divided by 42","correct_answer":"42 divided by 7"}'::jsonb, 'Divides in any order.', 'A choice of related facts.', 'The biggest number is the one you divide.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.DIVISION.MULT_DIV_RELATE.M_RELATE_CHECK_ADDS', 'MATH.G4.NUMBER.DIVISION.MULT_DIV_RELATE', 'Checks a division by adding the quotient and the divisor.', '{"question":"How can you check 56 divided by 7 = 8?","wrong_answer":"7 + 8","correct_answer":"8 x 7"}'::jsonb, 'Does not know the inverse.', 'A check-by-working question.', 'Multiplication undoes division.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.DIVISION.MULT_DIV_RELATE.M_RELATE_MISSING_ADDS', 'MATH.G4.NUMBER.DIVISION.MULT_DIV_RELATE', 'Finds a missing number in a multiplication by subtracting.', '{"question":"? x 6 = 54. What is ?","wrong_answer":"48","correct_answer":"9"}'::jsonb, 'Treats the unknown as a part of an addition.', 'A missing factor.', 'Use the related division: 54 divided by 6.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.DIVISION.DIV_NO_REMAINDER.M_DIV_TENS_REMAINDER_LOST', 'MATH.G4.NUMBER.DIVISION.DIV_NO_REMAINDER', 'Divides the tens, then drops the tens left over instead of joining them to the ones.', '{"question":"What is 52 ÷ 4?","wrong_answer":"10","correct_answer":"13"}'::jsonb, 'Treats each digit as a separate division.', 'The answer 10 as a wrong option, with a reason that names the idea.', 'Share 52 sticks: 5 bundles to 4 children, untie the extra bundle and share 12 loose sticks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.DIVISION.MULT_DIV_RELATE.M_RELATE_ONE_DIVISION_ONLY', 'MATH.G4.NUMBER.DIVISION.MULT_DIV_RELATE', 'Thinks one multiplication fact gives only one division fact.', '{"question":"6 x 7 = 42. Write two division facts.","wrong_answer":"42 ÷ 7 = 6 only","correct_answer":"42 ÷ 7 = 6 and 42 ÷ 6 = 7"}'::jsonb, 'Does not see the two ways to share the same array.', 'The answer 42 ÷ 7 = 6 only as a wrong option, with a reason that names the idea.', 'Turn the array round: 6 rows of 7 is also 7 rows of 6.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.FRACTIONS.NUM_DEN.M_FRAC_SWAP_NUM_DEN', 'MATH.G4.NUMBER.FRACTIONS.NUM_DEN', 'Mixes up the numerator and the denominator.', '{"question":"In 3/8, what is the denominator?","wrong_answer":"3","correct_answer":"8"}'::jsonb, 'Both words are new and sound alike.', 'A name-the-part question.', 'The denominator is down; it names the parts. The numerator is up; it numbers the parts taken.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.FRACTIONS.NUM_DEN.M_FRAC_TWO_NUMBERS_SEPARATE', 'MATH.G4.NUMBER.FRACTIONS.NUM_DEN', 'Treats a fraction as two whole numbers with no link.', '{"question":"What does the 8 in 3/8 tell you?","wrong_answer":"8 things are shaded","correct_answer":"the whole is cut into 8 equal parts"}'::jsonb, 'Reads the fraction as 3 and 8.', 'A question about meaning.', 'Cut and shade a paper strip and say it in words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.FRACTIONS.NUM_DEN.M_FRAC_PARTS_NOT_EQUAL', 'MATH.G4.NUMBER.FRACTIONS.NUM_DEN', 'Counts the parts without checking that they are equal.', '{"question":"A bar is cut into 4 pieces of different sizes, one shaded. What fraction is shaded?","wrong_answer":"1/4","correct_answer":"not a quarter: the parts are not equal"}'::jsonb, 'Counts the pieces and ignores their size.', 'A picture with unequal parts.', 'Fold a strip: equal parts match when put on top of each other.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.FRACTIONS.FRACTION_OF_WHOLE.M_FRAC_SHADED_OVER_UNSHADED', 'MATH.G4.NUMBER.FRACTIONS.FRACTION_OF_WHOLE', 'Writes shaded over unshaded instead of shaded over all parts.', '{"question":"5 of 8 parts are shaded. What fraction is shaded?","wrong_answer":"5/3","correct_answer":"5/8"}'::jsonb, 'Compares the two groups instead of using the whole.', 'A picture with shaded and unshaded parts.', 'The bottom number is all the parts, shaded and not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.FRACTIONS.FRACTION_OF_WHOLE.M_FRAC_COUNT_CUTS', 'MATH.G4.NUMBER.FRACTIONS.FRACTION_OF_WHOLE', 'Counts the cuts instead of the parts, so the denominator is one less.', '{"question":"A chapati is cut with 3 cuts into equal parts. How many parts?","wrong_answer":"3","correct_answer":"4"}'::jsonb, 'Counts the lines in the picture.', 'A drawing showing cut lines.', 'Count the pieces, not the lines.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.FRACTIONS.FRACTION_OF_WHOLE.M_FRAC_WRONG_NUMBER_OF_PARTS', 'MATH.G4.NUMBER.FRACTIONS.FRACTION_OF_WHOLE', 'Uses the number of parts shaded as the denominator.', '{"question":"A pizza has 12 equal slices; 3 are eaten. What fraction is eaten?","wrong_answer":"3/3","correct_answer":"3/12"}'::jsonb, 'Does not say the total number.', 'A story with a larger whole.', 'Say the total number of parts first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.FRACTIONS.FRACTION_OF_GROUP.M_FRAC_GROUP_PART_OVER_OTHER', 'MATH.G4.NUMBER.FRACTIONS.FRACTION_OF_GROUP', 'Writes the number with the property over the number without it.', '{"question":"3 of 8 goats are black. What fraction are black?","wrong_answer":"3/5","correct_answer":"3/8"}'::jsonb, 'Makes the fraction from the two groups.', 'A group story with two kinds.', 'The whole is the group of 8, all the goats.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.FRACTIONS.FRACTION_OF_GROUP.M_FRAC_OF_GROUP_DIVIDES_WRONG', 'MATH.G4.NUMBER.FRACTIONS.FRACTION_OF_GROUP', 'Divides by the numerator instead of the denominator when finding a fraction of a group.', '{"question":"What is 1/4 of 12?","wrong_answer":"12 divided by 1 = 12","correct_answer":"3"}'::jsonb, 'Divides by the top number.', 'A fraction-of-a-number question.', 'Share the group into as many equal sets as the denominator says.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.FRACTIONS.FRACTION_OF_GROUP.M_FRAC_OF_GROUP_ONE_PART_ONLY', 'MATH.G4.NUMBER.FRACTIONS.FRACTION_OF_GROUP', 'Finds one part and stops, though the numerator is more than one.', '{"question":"What is 3/4 of 12?","wrong_answer":"3","correct_answer":"9"}'::jsonb, 'Stops after dividing by 4.', 'A numerator greater than one.', 'One part is 12 divided by 4. How many parts do you take?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.FRACTIONS.TYPES_OF_FRACTIONS.M_TYPE_IMPROPER_NOT_FRACTION', 'MATH.G4.NUMBER.FRACTIONS.TYPES_OF_FRACTIONS', 'Says an improper fraction is not a real fraction.', '{"question":"Is 7/4 a fraction?","wrong_answer":"No, the top is bigger","correct_answer":"Yes, it is an improper fraction"}'::jsonb, 'Thinks fractions are always less than one.', 'A question with an improper fraction among the fractions.', 'Draw 7 quarters: it is more than a whole.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.FRACTIONS.TYPES_OF_FRACTIONS.M_TYPE_MIXED_AS_PROPER', 'MATH.G4.NUMBER.FRACTIONS.TYPES_OF_FRACTIONS', 'Calls a mixed fraction a proper fraction because it has a fraction part.', '{"question":"What kind of fraction is 2 1/3?","wrong_answer":"proper","correct_answer":"mixed"}'::jsonb, 'Sees the 1/3 and stops.', 'A mixed fraction among the options.', 'A mixed fraction has a whole number part.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.FRACTIONS.TYPES_OF_FRACTIONS.M_TYPE_EQUAL_IS_PROPER', 'MATH.G4.NUMBER.FRACTIONS.TYPES_OF_FRACTIONS', 'Calls a fraction with numerator equal to the denominator a proper fraction.', '{"question":"What kind of fraction is 5/5?","wrong_answer":"proper","correct_answer":"improper"}'::jsonb, 'Does not know that 5/5 is one whole.', 'A fraction like 6/6.', 'A proper fraction is less than one whole.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.FRACTIONS.IMPROPER_TO_MIXED.M_MIX_REMAINDER_AS_WHOLE', 'MATH.G4.NUMBER.FRACTIONS.IMPROPER_TO_MIXED', 'Gives the remainder as the whole number part.', '{"question":"Change 11/4 to a mixed fraction.","wrong_answer":"3 2/4","correct_answer":"2 3/4"}'::jsonb, 'Divides but mixes up the quotient and remainder.', 'An improper fraction with remainder bigger than the quotient.', 'The quotient is how many whole ones; the remainder is the parts left.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.FRACTIONS.IMPROPER_TO_MIXED.M_MIX_REMAINDER_OVER_QUOTIENT', 'MATH.G4.NUMBER.FRACTIONS.IMPROPER_TO_MIXED', 'Writes the remainder over the whole-number part instead of the denominator.', '{"question":"Change 17/5 to a mixed fraction.","wrong_answer":"3 2/3","correct_answer":"3 2/5"}'::jsonb, 'Uses the wrong number for the denominator.', 'A mixed fraction with the wrong denominator.', 'The parts are still fifths.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.FRACTIONS.IMPROPER_TO_MIXED.M_MIX_NO_REMAINDER_LEFT_OUT', 'MATH.G4.NUMBER.FRACTIONS.IMPROPER_TO_MIXED', 'Does not write the fraction part when the division is exact.', '{"question":"Change 12/4 to a whole number or mixed.","wrong_answer":"3 0/4","correct_answer":"3"}'::jsonb, 'Keeps a zero fraction.', 'An improper fraction that divides exactly.', '12 quarters make exactly 3 wholes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.FRACTIONS.MIXED_TO_IMPROPER.M_IMP_ADDS_WHOLE', 'MATH.G4.NUMBER.FRACTIONS.MIXED_TO_IMPROPER', 'Adds the whole number to the numerator.', '{"question":"Change 2 3/5 to an improper fraction.","wrong_answer":"5/5","correct_answer":"13/5"}'::jsonb, 'Adds the whole number and the numerator and keeps the denominator.', 'A mixed fraction with a numerator different from the whole.', 'Each whole is 5 fifths; two wholes are 10 fifths.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.FRACTIONS.MIXED_TO_IMPROPER.M_IMP_WHOLE_TIMES_NUMERATOR', 'MATH.G4.NUMBER.FRACTIONS.MIXED_TO_IMPROPER', 'Multiplies the whole number by the numerator and not by the denominator.', '{"question":"Change 3 2/5 to an improper fraction.","wrong_answer":"11/5","correct_answer":"17/5"}'::jsonb, 'Multiplies the wrong two numbers.', 'A mixed fraction with unequal numerator and denominator.', 'Each whole has as many parts as the denominator says.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
