INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.DECIMALS.DECIMAL_NOTATION.M_DEC_READ_AS_WHOLE', 'MATH.G4.NUMBER.DECIMALS.DECIMAL_NOTATION', 'Reads 0.37 as nought point thirty-seven.', '{"question":"How do you read 0.37?","wrong_answer":"nought point thirty-seven","correct_answer":"nought point three seven"}'::jsonb, 'Treats the digits after the point as a whole number.', 'A read-aloud or word choice.', 'Say each digit after the point on its own.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
