INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.DECIMALS.DECIMAL_PLACE_VALUE.M_DEC_ZERO_PLACE_HOLDER', 'MATH.G4.NUMBER.DECIMALS.DECIMAL_PLACE_VALUE', 'Drops the zero in a number like 5.07 or misplaces the 7.', '{"question":"Which place is the 7 in 5.07?","wrong_answer":"tenths","correct_answer":"hundredths"}'::jsonb, 'Ignores the zero.', 'A decimal with a zero in the tenths place.', 'The zero holds the tenths place.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.DECIMALS.ORDER_DECIMALS.M_DEC_LONGER_IS_LARGER', 'MATH.G4.NUMBER.DECIMALS.ORDER_DECIMALS', 'Thinks the decimal with more digits is larger.', '{"question":"Which is larger, 0.6 or 0.58?","wrong_answer":"0.58","correct_answer":"0.6"}'::jsonb, 'Applies the whole-number rule: more digits is bigger.', 'A pair like 0.6 and 0.58 or 0.3 and 0.25.', 'Write both with two decimal places: 0.60 and 0.58.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
