INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.DECIMALS.ORDER_DECIMALS.M_DEC_ORDER_DIRECTION', 'MATH.G4.NUMBER.DECIMALS.ORDER_DECIMALS', 'Gives the order from largest to smallest when asked for smallest to largest.', '{"question":"Order smallest to largest: 0.4, 0.04, 0.44.","wrong_answer":"0.44, 0.4, 0.04","correct_answer":"0.04, 0.4, 0.44"}'::jsonb, 'Does not read the direction.', 'The reversed list as an option.', 'Underline the direction words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.DECIMALS.TENTH_HUNDREDTH.M_DEC_HUNDREDTH_BIGGER', 'MATH.G4.NUMBER.DECIMALS.TENTH_HUNDREDTH', 'Thinks a hundredth is bigger than a tenth because 100 is bigger than 10.', '{"question":"Which is bigger, 1/10 or 1/100?","wrong_answer":"1/100","correct_answer":"1/10"}'::jsonb, 'Compares the denominators as whole numbers.', 'The answer 1/100 as a wrong option, with a reason that names the idea.', 'Shade one column and one small square of a hundred square and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.DECIMALS.DECIMAL_NOTATION.M_DEC_TENTHS_OVER_TEN', 'MATH.G4.NUMBER.DECIMALS.DECIMAL_NOTATION', 'Writes more than ten tenths after the point as a two-digit decimal.', '{"question":"Write 12/10 as a decimal.","wrong_answer":"0.12","correct_answer":"1.2"}'::jsonb, 'Writes the numerator after the point whatever its size.', 'The answer 0.12 as a wrong option, with a reason that names the idea.', 'Ten tenths make one whole: 12 tenths are 1 whole and 2 tenths.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.DECIMALS.DECIMAL_PLACE_VALUE.M_DEC_PLACES_REVERSED', 'MATH.G4.NUMBER.DECIMALS.DECIMAL_PLACE_VALUE', 'Names the places after the point the wrong way round.', '{"question":"In 3.48, which place is the 8 in?","wrong_answer":"tenths","correct_answer":"hundredths"}'::jsonb, 'Mirrors the whole-number places: thinks the place nearest the right end is tenths, like tens.', 'The answer tenths as a wrong option, with a reason that names the idea.', 'Name the places moving right from the point: tenths first, then hundredths.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.DECIMALS.ORDER_DECIMALS.M_DEC_SHORTER_IS_LARGER', 'MATH.G4.NUMBER.DECIMALS.ORDER_DECIMALS', 'Thinks a decimal with fewer digits after the point is larger, because tenths are bigger than hundredths.', '{"question":"Which is larger, 0.3 or 0.35?","wrong_answer":"0.3","correct_answer":"0.35"}'::jsonb, 'Knows tenths are bigger pieces and decides by the length.', 'The answer 0.3 as a wrong option, with a reason that names the idea.', 'Write 0.3 as 0.30 and compare 30 hundredths with 35 hundredths.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.USE_OF_LETTERS.LETTERS_REPRESENT.M_LET_LETTER_IS_ITS_ALPHABET_POSITION', 'MATH.G4.NUMBER.USE_OF_LETTERS.LETTERS_REPRESENT', 'Thinks a letter always has a fixed value from its place in the alphabet.', '{"question":"What is a + 2 if a = 5?","wrong_answer":"3","correct_answer":"7"}'::jsonb, 'Learned a = 1, b = 2.', 'A question with a given value of a letter.', 'The letter stands for the number the story or the question says.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.USE_OF_LETTERS.LETTERS_REPRESENT.M_LET_LETTER_IS_OBJECT', 'MATH.G4.NUMBER.USE_OF_LETTERS.LETTERS_REPRESENT', 'Reads the letter as the name of an object, such as b for bananas rather than the number of bananas.', '{"question":"b stands for bananas. What does 3b mean?","wrong_answer":"3 bananas","correct_answer":"3 times the number of bananas"}'::jsonb, 'Reads the letter as a label, as in 3b meaning 3 bananas.', 'A letter used for a number of objects.', 'b is the number of bananas in one bunch.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.USE_OF_LETTERS.LETTERS_REPRESENT.M_LET_DIFFERENT_LETTERS_DIFFERENT_NUMBERS', 'MATH.G4.NUMBER.USE_OF_LETTERS.LETTERS_REPRESENT', 'Says different letters must stand for different numbers, or the same letter for different numbers.', '{"question":"If x = 4, what is y + y if y = 4?","wrong_answer":"x and y must be different","correct_answer":"8"}'::jsonb, 'Thinks each letter is unique in value.', 'A question where two letters have the same value.', 'Letters are labels for the number given.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.USE_OF_LETTERS.FORM_EXPRESSIONS.M_EXP_NOT_NUMBER_WORD', 'MATH.G4.NUMBER.USE_OF_LETTERS.FORM_EXPRESSIONS', 'Writes the number and the letter together without a sign, as 5b, for 5 + b.', '{"question":"Ann has 5 books and gets b more. Write the total.","wrong_answer":"5b","correct_answer":"5 + b"}'::jsonb, 'Puts the letter beside the number.', 'A story of a total.', '5b means 5 times b. Use + for more.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.USE_OF_LETTERS.FORM_EXPRESSIONS.M_EXP_WRONG_OPERATION', 'MATH.G4.NUMBER.USE_OF_LETTERS.FORM_EXPRESSIONS', 'Uses the wrong sign for the story.', '{"question":"A bag has m mangoes. Write the mangoes in 3 bags.","wrong_answer":"m + 3","correct_answer":"3 x m"}'::jsonb, 'Always adds.', 'A story with equal groups.', 'Draw 3 bags and write m for each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.USE_OF_LETTERS.FORM_EXPRESSIONS.M_EXP_ORDER_OF_SUBTRACTION', 'MATH.G4.NUMBER.USE_OF_LETTERS.FORM_EXPRESSIONS', 'Writes the numbers in the order they appear in the story, reversing a subtraction.', '{"question":"Tom had t shillings and spent 20. Write what is left.","wrong_answer":"20 - t","correct_answer":"t - 20"}'::jsonb, 'Follows the story word by word.', 'A spend story.', 'Start with what Tom had.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.USE_OF_LETTERS.SIMPLIFY_EXPRESSIONS.M_SIM_ADD_UNLIKE', 'MATH.G4.NUMBER.USE_OF_LETTERS.SIMPLIFY_EXPRESSIONS', 'Adds unlike terms as if they were the same.', '{"question":"Simplify 3a + 2b.","wrong_answer":"5ab","correct_answer":"3a + 2b"}'::jsonb, 'Thinks all terms can combine.', 'An expression with two different letters.', 'Apples and bananas cannot be added into one kind.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.USE_OF_LETTERS.SIMPLIFY_EXPRESSIONS.M_SIM_LETTER_DROPPED', 'MATH.G4.NUMBER.USE_OF_LETTERS.SIMPLIFY_EXPRESSIONS', 'Adds the numbers and drops the letter.', '{"question":"Simplify 3a + 2a.","wrong_answer":"5","correct_answer":"5a"}'::jsonb, 'Does not see that the letter stays.', 'Like terms.', 'It is 3 of a and 2 of a: 5 of a.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.USE_OF_LETTERS.SIMPLIFY_EXPRESSIONS.M_SIM_LETTER_SQUARED', 'MATH.G4.NUMBER.USE_OF_LETTERS.SIMPLIFY_EXPRESSIONS', 'Adds the numbers and doubles the letter (3a + 2a = 5aa or 5a2).', '{"question":"Simplify 4b + 3b.","wrong_answer":"7bb","correct_answer":"7b"}'::jsonb, 'Writes the letter for each term.', 'Like terms.', 'The letter shows what is counted and stays one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.USE_OF_LETTERS.SIMPLIFY_EXPRESSIONS.M_SIM_SUBTRACT_WRONG', 'MATH.G4.NUMBER.USE_OF_LETTERS.SIMPLIFY_EXPRESSIONS', 'Subtracts the numbers the wrong way round or adds them.', '{"question":"Simplify 7b - 3b.","wrong_answer":"10b","correct_answer":"4b"}'::jsonb, 'Does not follow the sign.', 'A subtraction of like terms.', 'You had 7 and took away 3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.USE_OF_LETTERS.LETTERS_REPRESENT.M_LET_LETTER_IGNORED', 'MATH.G4.NUMBER.USE_OF_LETTERS.LETTERS_REPRESENT', 'Leaves the letter out and works with the numbers only.', '{"question":"If n = 6, what is n + 4?","wrong_answer":"4","correct_answer":"10"}'::jsonb, 'Does not see the letter as standing for a number.', 'The answer 4 as a wrong option, with a reason that names the idea.', 'Put the number in place of the letter first: 6 + 4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.USE_OF_LETTERS.LETTERS_REPRESENT.M_LET_JOINED_AS_DIGITS', 'MATH.G4.NUMBER.USE_OF_LETTERS.LETTERS_REPRESENT', 'Puts the value next to the number as digits, so 3p with p = 20 becomes 320.', '{"question":"A pencil costs p shillings and p = 20. What is 3p?","wrong_answer":"320","correct_answer":"60"}'::jsonb, 'Reads 3p like a two-digit number.', 'The answer 320 as a wrong option, with a reason that names the idea.', '3p means 3 x p: 3 lots of 20.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.USE_OF_LETTERS.LETTERS_REPRESENT.M_LET_COEFFICIENT_ADDED', 'MATH.G4.NUMBER.USE_OF_LETTERS.LETTERS_REPRESENT', 'Adds the number in front to the letter''s value.', '{"question":"If p = 20, what is 3p?","wrong_answer":"23","correct_answer":"60"}'::jsonb, 'Joins the 3 and the p by adding.', 'The answer 23 as a wrong option, with a reason that names the idea.', '3p means 3 lots of p, so multiply.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.NUMBER.USE_OF_LETTERS.FORM_EXPRESSIONS.M_EXP_GUESSES_NUMBER', 'MATH.G4.NUMBER.USE_OF_LETTERS.FORM_EXPRESSIONS', 'Writes a number for an amount that is not known, instead of a letter.', '{"question":"Wanjiru has some sweets, s. She gets 4 more. Write an expression for her sweets.","wrong_answer":"8","correct_answer":"s + 4"}'::jsonb, 'Feels an answer must be a number.', 'The answer 8 as a wrong option, with a reason that names the idea.', 'We do not know s, so keep the letter: s + 4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.LENGTH.CM_UNIT.M_LEN_WRONG_UNIT', 'MATH.G4.MEASUR.LENGTH.CM_UNIT', 'Chooses a metre for a short length such as a pencil, or a centimetre for the length of a room.', '{"question":"Which unit would you use for the length of a pencil?","wrong_answer":"metres","correct_answer":"centimetres"}'::jsonb, 'Has no sense of how long each unit is.', 'A pick-the-unit question with a short and a long object.', 'Put a metre rule next to the pencil and look.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.LENGTH.CM_UNIT.M_LEN_CM_AS_M_SIZE', 'MATH.G4.MEASUR.LENGTH.CM_UNIT', 'Thinks a centimetre is about as long as a finger, or a hand.', '{"question":"About how long is 1 cm?","wrong_answer":"the length of a hand","correct_answer":"the width of a fingernail"}'::jsonb, 'Has not handled a ruler.', 'A size choice.', 'Mark 1 cm on paper and compare with a fingernail.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.LENGTH.MEASURE_CM.M_LEN_NOT_FROM_ZERO', 'MATH.G4.MEASUR.LENGTH.MEASURE_CM', 'Reads the number at the right end of the object, though the object starts at 2 not 0.', '{"question":"A pencil lies from 2 cm to 9 cm on a ruler. How long is it?","wrong_answer":"9 cm","correct_answer":"7 cm"}'::jsonb, 'Does not see the zero line.', 'A picture of an object that starts at 2 or 3 on the ruler.', 'Count the cm gaps, not the numbers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.LENGTH.MEASURE_CM.M_LEN_COUNTS_MARKS', 'MATH.G4.MEASUR.LENGTH.MEASURE_CM', 'Counts the marks instead of the gaps between them.', '{"question":"A line goes from the 0 mark to the 6 mark on a ruler. How long is it?","wrong_answer":"7 cm","correct_answer":"6 cm"}'::jsonb, 'Counts the starting mark.', 'A ruler picture with the marks drawn.', 'Count the spaces between marks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.LENGTH.MEASURE_CM.M_LEN_DIFFERENCE_AS_END', 'MATH.G4.MEASUR.LENGTH.MEASURE_CM', 'Gives the end reading when asked how much longer one object is than another.', '{"question":"A rope is 9 cm and a string is 4 cm. How much longer is the rope?","wrong_answer":"9 cm","correct_answer":"5 cm"}'::jsonb, 'Does not subtract.', 'A compare question.', 'Draw the two lines under each other.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.LENGTH.M_CM_RELATION.M_LEN_10_NOT_100', 'MATH.G4.MEASUR.LENGTH.M_CM_RELATION', 'Says there are 10 centimetres in a metre.', '{"question":"How many centimetres in 1 metre?","wrong_answer":"10","correct_answer":"100"}'::jsonb, 'Mixes up with millimetres in a centimetre or tens place value.', 'A fact question.', 'Look at a metre ruler: count tens, ten of them make 100.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.LENGTH.M_CM_RELATION.M_LEN_HALF_METRE_WRONG', 'MATH.G4.MEASUR.LENGTH.M_CM_RELATION', 'Says half a metre is 5 cm or 25 cm.', '{"question":"Half a metre is how many centimetres?","wrong_answer":"25 cm","correct_answer":"50 cm"}'::jsonb, 'Halves 10 or mixes with a quarter.', 'A half and a quarter of a metre in one question.', 'Half of 100 is 50.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.LENGTH.CONVERT_M_CM.M_CONV_ADD_DIGITS', 'MATH.G4.MEASUR.LENGTH.CONVERT_M_CM', 'Joins the digits of the metres and the centimetres without a place holder zero.', '{"question":"Write 3 m 4 cm in centimetres.","wrong_answer":"34 cm","correct_answer":"304 cm"}'::jsonb, 'Does not keep the place for the tens of cm.', 'A length with a single digit of cm.', 'Metres are hundreds of cm: 3 m is 300 cm, then add 4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.LENGTH.CONVERT_M_CM.M_CONV_WRONG_FACTOR', 'MATH.G4.MEASUR.LENGTH.CONVERT_M_CM', 'Multiplies by 10 instead of 100, or by 1,000.', '{"question":"Change 6 m to centimetres.","wrong_answer":"60 cm","correct_answer":"600 cm"}'::jsonb, 'Has no fixed fact for the number of centimetres in a metre.', 'A metres to centimetres conversion.', 'One metre is 100 cm, so 6 m is 6 x 100.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.LENGTH.CONVERT_M_CM.M_CONV_DIRECTION', 'MATH.G4.MEASUR.LENGTH.CONVERT_M_CM', 'Divides when changing to the smaller unit or multiplies when changing to the larger.', '{"question":"Change 400 cm to metres.","wrong_answer":"40000 m","correct_answer":"4 m"}'::jsonb, 'Does not see that a smaller unit gives a bigger number.', 'A cm to m conversion.', 'A metre is bigger than a centimetre, so there are fewer metres.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.LENGTH.PERIMETER.M_PER_TWO_SIDES_ONLY', 'MATH.G4.MEASUR.LENGTH.PERIMETER', 'Adds only the length and the width of a rectangle.', '{"question":"A rectangle is 8 cm long and 5 cm wide. What is its perimeter?","wrong_answer":"13 cm","correct_answer":"26 cm"}'::jsonb, 'Confuses perimeter with half the perimeter.', 'A rectangle perimeter question.', 'Walk round the rectangle: count every side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.LENGTH.PERIMETER.M_PER_AREA_NOT_PERIMETER', 'MATH.G4.MEASUR.LENGTH.PERIMETER', 'Multiplies the length and the width, giving the area.', '{"question":"A plot is 12 m long and 7 m wide. How long is the fence round it?","wrong_answer":"84 m","correct_answer":"38 m"}'::jsonb, 'Does not tell perimeter from area.', 'A fencing story.', 'Ask: do I go around the edge or cover the inside?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.LENGTH.PERIMETER.M_PER_SQUARE_ONE_SIDE', 'MATH.G4.MEASUR.LENGTH.PERIMETER', 'Gives one side as the perimeter of a square.', '{"question":"A square has a side of 6 cm. What is its perimeter?","wrong_answer":"6 cm","correct_answer":"24 cm"}'::jsonb, 'Does not see that there are four equal sides.', 'A square with one side given.', 'Mark each side with a tick as you add.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.LENGTH.LENGTH_ADD.M_LADD_NO_REGROUP', 'MATH.G4.MEASUR.LENGTH.LENGTH_ADD', 'Writes more than 99 cm in the centimetre column.', '{"question":"2 m 70 cm + 1 m 50 cm","wrong_answer":"3 m 120 cm","correct_answer":"4 m 20 cm"}'::jsonb, 'Does not change 100 cm into 1 m.', 'Lengths whose cm add to more than 100.', '100 cm is 1 m: move it to the metre column.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.LENGTH.LENGTH_ADD.M_LADD_ADDS_ACROSS', 'MATH.G4.MEASUR.LENGTH.LENGTH_ADD', 'Adds metres to centimetres.', '{"question":"1 m 20 cm + 2 m 30 cm","wrong_answer":"53 m","correct_answer":"3 m 50 cm"}'::jsonb, 'Ignores the unit labels.', 'A sum with units.', 'Add like units only: metres with metres.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.LENGTH.LENGTH_SUB.M_LSUB_SMALLER_FROM_LARGER', 'MATH.G4.MEASUR.LENGTH.LENGTH_SUB', 'Takes the smaller number of centimetres from the larger regardless of order.', '{"question":"5 m 20 cm - 2 m 70 cm","wrong_answer":"3 m 50 cm","correct_answer":"2 m 50 cm"}'::jsonb, 'Subtracts 20 from 70 and 2 from 5.', 'Lengths where the cm to subtract is bigger.', 'Change 1 m to 100 cm first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.LENGTH.LENGTH_SUB.M_LSUB_BORROW_100_NOT_10', 'MATH.G4.MEASUR.LENGTH.LENGTH_SUB', 'Borrows 10 centimetres instead of 100.', '{"question":"4 m 30 cm - 1 m 60 cm","wrong_answer":"2 m 80 cm","correct_answer":"2 m 70 cm"}'::jsonb, 'Uses the tens borrow as in numbers.', 'A regrouping with metres.', 'One metre is 100 cm: so 130 - 60.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.LENGTH.LENGTH_MULT.M_LMUL_NO_REGROUP', 'MATH.G4.MEASUR.LENGTH.LENGTH_MULT', 'Leaves more than 99 cm in the centimetre column after multiplying.', '{"question":"2 m 60 cm x 4","wrong_answer":"8 m 240 cm","correct_answer":"10 m 40 cm"}'::jsonb, 'Multiplies metres and cm separately and does not regroup.', 'A cm part that goes over 100.', '4 x 60 cm is 240 cm, which is 2 m 40 cm: change the extra 100 cm into metres.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.LENGTH.LENGTH_MULT.M_LMUL_ONLY_METRES', 'MATH.G4.MEASUR.LENGTH.LENGTH_MULT', 'Multiplies the metres and keeps the centimetres unchanged.', '{"question":"2 m 30 cm x 3","wrong_answer":"6 m 30 cm","correct_answer":"6 m 90 cm"}'::jsonb, 'Does not multiply both parts.', 'A length with a cm part.', 'Multiply the cm too.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.LENGTH.LENGTH_DIV.M_LDIV_METRES_ONLY', 'MATH.G4.MEASUR.LENGTH.LENGTH_DIV', 'Divides the metres and leaves the centimetres whole.', '{"question":"4 m 80 cm divided by 4","wrong_answer":"1 m 80 cm","correct_answer":"1 m 20 cm"}'::jsonb, 'Divides one part only.', 'A length with cm.', 'Change to cm: 480 cm divided by 4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.LENGTH.LENGTH_DIV.M_LDIV_REMAINDER_METRES_LOST', 'MATH.G4.MEASUR.LENGTH.LENGTH_DIV', 'Loses the remainder of metres when dividing, as in 5 m divided by 2 giving 2 m.', '{"question":"5 m divided by 2","wrong_answer":"2 m","correct_answer":"2 m 50 cm"}'::jsonb, 'Stops at the whole number of metres.', 'An odd number of metres.', 'Change 5 m to 500 cm first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.LENGTH.CM_UNIT.M_LEN_BIGGER_NUMBER_LONGER', 'MATH.G4.MEASUR.LENGTH.CM_UNIT', 'Thinks 30 cm is longer than 2 m because 30 is a bigger number than 2.', '{"question":"Which is longer, 30 cm or 2 m?","wrong_answer":"30 cm","correct_answer":"2 m"}'::jsonb, 'Compares the numbers and ignores the units.', 'The answer 30 cm as a wrong option, with a reason that names the idea.', 'Change to the same unit first: 2 m is 200 cm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.LENGTH.CM_UNIT.M_LEN_ESTIMATE_FAR_OUT', 'MATH.G4.MEASUR.LENGTH.CM_UNIT', 'Estimates a length in centimetres far too big or too small.', '{"question":"About how long is an exercise book?","wrong_answer":"200 cm","correct_answer":"about 20 cm"}'::jsonb, 'Has no picture of how long 1 cm and 10 cm are.', 'The answer 200 cm as a wrong option, with a reason that names the idea.', 'Use body benchmarks: a fingernail is about 1 cm, a hand span about 15 cm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.LENGTH.MEASURE_CM.M_LEN_STARTS_AT_ONE', 'MATH.G4.MEASUR.LENGTH.MEASURE_CM', 'Lines the object up with the 1 mark, because counting starts at 1.', '{"question":"Kamau puts the end of his pencil at the 1 mark and the tip is at 9. He says 9 cm. How long is it?","wrong_answer":"9 cm","correct_answer":"8 cm"}'::jsonb, 'Thinks the ruler starts at 1, as counting does.', 'The answer 9 cm as a wrong option, with a reason that names the idea.', 'Count the gaps, not the marks: the first centimetre is the gap from 0 to 1.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.LENGTH.M_CM_RELATION.M_LEN_1000_CM', 'MATH.G4.MEASUR.LENGTH.M_CM_RELATION', 'Says there are 1,000 centimetres in a metre.', '{"question":"How many centimetres in 1 metre?","wrong_answer":"1,000","correct_answer":"100"}'::jsonb, 'Mixes the centimetre with kilo- facts heard elsewhere.', 'The answer 1,000 as a wrong option, with a reason that names the idea.', 'Lay ten 10 cm strips along a metre stick and count in tens.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.LENGTH.M_CM_RELATION.M_LEN_ADDS_100_FOR_METRES', 'MATH.G4.MEASUR.LENGTH.M_CM_RELATION', 'Adds 100 to the number of metres instead of multiplying.', '{"question":"How many centimetres in 3 metres?","wrong_answer":"103","correct_answer":"300"}'::jsonb, 'Remembers "100" but not that each metre is 100 cm.', 'The answer 103 as a wrong option, with a reason that names the idea.', 'Count in hundreds, one hundred for each metre: 100, 200, 300.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.LENGTH.CONVERT_M_CM.M_CONV_LEFTOVER_CM_LOST', 'MATH.G4.MEASUR.LENGTH.CONVERT_M_CM', 'Changes centimetres to metres and drops the centimetres left over.', '{"question":"Change 350 cm to metres and centimetres.","wrong_answer":"3 m","correct_answer":"3 m 50 cm"}'::jsonb, 'Stops after the whole metres.', 'The answer 3 m as a wrong option, with a reason that names the idea.', 'After taking out the metres, write what is left as centimetres.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.LENGTH.PERIMETER.M_PER_SIDE_MISSED', 'MATH.G4.MEASUR.LENGTH.PERIMETER', 'Leaves out a side of a shape with more than four sides.', '{"question":"A shape has sides of 3 cm, 4 cm, 5 cm, 2 cm and 6 cm. What is its perimeter?","wrong_answer":"14 cm","correct_answer":"20 cm"}'::jsonb, 'Adds four sides out of habit.', 'The answer 14 cm as a wrong option, with a reason that names the idea.', 'Tick each side as you add it, going round the shape once.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.LENGTH.LENGTH_ADD.M_LADD_100_CM_AS_10_M', 'MATH.G4.MEASUR.LENGTH.LENGTH_ADD', 'Changes 100 cm into 10 m when regrouping.', '{"question":"2 m 70 cm + 1 m 50 cm","wrong_answer":"13 m 20 cm","correct_answer":"4 m 20 cm"}'::jsonb, 'Treats the regrouping like tens.', 'The answer 13 m 20 cm as a wrong option, with a reason that names the idea.', 'Only 100 cm make 1 m: carry 1 metre.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.LENGTH.LENGTH_ADD.M_LADD_CM_DROPPED', 'MATH.G4.MEASUR.LENGTH.LENGTH_ADD', 'Adds the metres and leaves the centimetres out of the answer.', '{"question":"1 m 45 cm + 2 m 30 cm","wrong_answer":"3 m","correct_answer":"3 m 75 cm"}'::jsonb, 'Works only with the bigger unit.', 'The answer 3 m as a wrong option, with a reason that names the idea.', 'Add the centimetres first, then the metres.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.LENGTH.LENGTH_SUB.M_LSUB_ADDS', 'MATH.G4.MEASUR.LENGTH.LENGTH_SUB', 'Adds when the story asks how much longer.', '{"question":"A rope is 5 m 40 cm and a string is 2 m 10 cm. How much longer is the rope?","wrong_answer":"7 m 50 cm","correct_answer":"3 m 30 cm"}'::jsonb, 'Sees two lengths and adds them.', 'The answer 7 m 50 cm as a wrong option, with a reason that names the idea.', '"How much longer" is a difference: take away.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.LENGTH.LENGTH_SUB.M_LSUB_METRE_NOT_REDUCED', 'MATH.G4.MEASUR.LENGTH.LENGTH_SUB', 'Changes a metre into 100 cm but does not take 1 from the metres.', '{"question":"4 m 30 cm - 1 m 60 cm","wrong_answer":"3 m 70 cm","correct_answer":"2 m 70 cm"}'::jsonb, 'Forgets where the 100 cm came from.', 'The answer 3 m 70 cm as a wrong option, with a reason that names the idea.', 'Cross out the 4 m and write 3 m as soon as you borrow.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.LENGTH.LENGTH_MULT.M_LMUL_CARRY_NOT_ADDED', 'MATH.G4.MEASUR.LENGTH.LENGTH_MULT', 'Regroups 100 cm into a metre but forgets to add it to the metres.', '{"question":"2 m 60 cm x 4","wrong_answer":"8 m 40 cm","correct_answer":"10 m 40 cm"}'::jsonb, 'Writes the 40 cm left and loses the 2 m carried.', 'The answer 8 m 40 cm as a wrong option, with a reason that names the idea.', 'Write the carried metres above the metres column before multiplying them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.LENGTH.LENGTH_MULT.M_LMUL_ADDS_NUMBER', 'MATH.G4.MEASUR.LENGTH.LENGTH_MULT', 'Adds the number to the length instead of multiplying.', '{"question":"1 m 20 cm x 3","wrong_answer":"4 m 20 cm","correct_answer":"3 m 60 cm"}'::jsonb, 'Treats "times" like "and".', 'The answer 4 m 20 cm as a wrong option, with a reason that names the idea.', 'x 3 means three pieces of 1 m 20 cm laid end to end.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.LENGTH.LENGTH_DIV.M_LDIV_MULTIPLIES', 'MATH.G4.MEASUR.LENGTH.LENGTH_DIV', 'Multiplies when a length is cut into equal pieces.', '{"question":"6 m 30 cm of rope is cut into 3 equal pieces. How long is each piece?","wrong_answer":"18 m 90 cm","correct_answer":"2 m 10 cm"}'::jsonb, 'Sees two numbers and multiplies.', 'The answer 18 m 90 cm as a wrong option, with a reason that names the idea.', 'Each piece is shorter than the whole rope: divide.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.LENGTH.LENGTH_DIV.M_LDIV_REMAINDER_AS_CM', 'MATH.G4.MEASUR.LENGTH.LENGTH_DIV', 'Writes the metres left over as the same number of centimetres.', '{"question":"7 m ÷ 2","wrong_answer":"3 m 1 cm","correct_answer":"3 m 50 cm"}'::jsonb, 'Keeps the remainder digit and changes its unit.', 'The answer 3 m 1 cm as a wrong option, with a reason that names the idea.', 'The metre left over is 100 cm: share 100 cm between 2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.AREA.COMPARE_AREA.M_AREA_LONGER_IS_LARGER', 'MATH.G4.MEASUR.AREA.COMPARE_AREA', 'Says the longer shape has the larger area.', '{"question":"Shape A is a long thin strip of 10 squares. Shape B is a 3 by 4 rectangle of 12 squares. Which is larger?","wrong_answer":"A","correct_answer":"B"}'::jsonb, 'Compares one length instead of the whole surface.', 'A long, thin shape against a compact one.', 'Cover each one with squares and count.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.AREA.COMPARE_AREA.M_AREA_COUNTS_EDGES', 'MATH.G4.MEASUR.AREA.COMPARE_AREA', 'Compares the edges of two shapes instead of the surface.', '{"question":"Shape A has a longer edge than shape B but fewer squares. Which has the larger area?","wrong_answer":"A","correct_answer":"B"}'::jsonb, 'Mixes area with perimeter.', 'Two shapes with the same perimeter and different areas.', 'Area is how much surface is covered.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.AREA.AREA_COUNT.M_AREA_COUNTS_EDGE_ONLY', 'MATH.G4.MEASUR.AREA.AREA_COUNT', 'Counts only the squares along the border.', '{"question":"A 4 by 3 rectangle on a grid. How many squares cover it?","wrong_answer":"10","correct_answer":"12"}'::jsonb, 'Counts the outside squares only.', 'A rectangle at least 3 by 3.', 'Count row by row.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.AREA.AREA_COUNT.M_AREA_COUNTS_TWICE', 'MATH.G4.MEASUR.AREA.AREA_COUNT', 'Counts a square twice or misses one.', '{"question":"A 3 by 5 rectangle. How many squares?","wrong_answer":"16","correct_answer":"15"}'::jsonb, 'Loses track of what has been counted.', 'A grid with no marks.', 'Mark each square as it is counted.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.AREA.AREA_COUNT.M_AREA_UNIT_LENGTH', 'MATH.G4.MEASUR.AREA.AREA_COUNT', 'Gives the answer as a length, in cm, not in squares.', '{"question":"Area of a rectangle covered by 12 unit squares?","wrong_answer":"12 cm","correct_answer":"12 squares"}'::jsonb, 'Treats area as another length.', 'An answer in units of area.', 'Area is how many squares cover the surface.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.AREA.AREA_ROWS_COLS.M_AREA_ADDS_ROWS_COLS', 'MATH.G4.MEASUR.AREA.AREA_ROWS_COLS', 'Adds the rows and columns.', '{"question":"A rectangle has 4 rows of 6 squares. What is its area?","wrong_answer":"10","correct_answer":"24"}'::jsonb, 'Adds the two numbers given.', 'A rows and columns question.', 'Draw 4 rows of 6.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.AREA.AREA_ROWS_COLS.M_AREA_PERIMETER_NOT_AREA', 'MATH.G4.MEASUR.AREA.AREA_ROWS_COLS', 'Gives the perimeter when asked for the area.', '{"question":"A rectangle has 5 rows of 4 squares. What is its area?","wrong_answer":"18","correct_answer":"20"}'::jsonb, 'Adds all four sides.', 'A rows and columns question where 2(r + c) differs from r x c.', 'Cover the inside with squares and count.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.AREA.AREA_ROWS_COLS.M_AREA_MISSING_ROW_ADDS', 'MATH.G4.MEASUR.AREA.AREA_ROWS_COLS', 'Subtracts to find a missing number of rows.', '{"question":"A rectangle has an area of 24 squares and 6 columns. How many rows?","wrong_answer":"18","correct_answer":"4"}'::jsonb, 'Treats the unknown as subtraction.', 'A missing row or column.', 'Rows times columns is the area, so divide.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.AREA.COMPARE_AREA.M_AREA_CUT_CHANGES', 'MATH.G4.MEASUR.AREA.COMPARE_AREA', 'Thinks cutting a shape and moving the pieces changes its area.', '{"question":"A paper square is cut into two triangles and put together as one big triangle. Is the area bigger, smaller or the same?","wrong_answer":"bigger","correct_answer":"the same"}'::jsonb, 'Judges by how the shape looks, not by the paper it uses.', 'The answer bigger as a wrong option, with a reason that names the idea.', 'Put the two triangles back on the square: they cover it exactly.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
