INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.TIME.RECORD_DURATION.M_TIME_DURATION_WRONG_UNITS', 'MATH.G4.MEASUR.TIME.RECORD_DURATION', 'Writes a duration such as 1 hour 30 minutes as 1.30 hours.', '{"question":"Write 1 hour 30 minutes in minutes.","wrong_answer":"130","correct_answer":"90"}'::jsonb, 'Treats the minutes as digits after a point.', 'A hour-minute duration.', '1 hour is 60 minutes, then add 30.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.TIME.WORK_OUT_DURATION.M_TIME_SUBTRACT_AS_DECIMAL', 'MATH.G4.MEASUR.TIME.WORK_OUT_DURATION', 'Subtracts the hours and minutes like decimals.', '{"question":"From 8:45 to 10:15 is how long?","wrong_answer":"1 hour 70 minutes","correct_answer":"1 hour 30 minutes"}'::jsonb, 'Does not regroup in sixties.', 'A duration across an hour.', 'Count up to the next hour, then the rest.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.TIME.WORK_OUT_DURATION.M_TIME_ADD_MINUTES_OVER_60', 'MATH.G4.MEASUR.TIME.WORK_OUT_DURATION', 'Leaves more than 59 minutes in the minutes part.', '{"question":"A film starts at 5:40 and lasts 50 minutes. When does it end?","wrong_answer":"5:90","correct_answer":"6:30"}'::jsonb, 'Does not carry into hours.', 'A time to which minutes are added.', '60 minutes make 1 hour.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.TIME.WORK_OUT_DURATION.M_TIME_NOON_AMPM', 'MATH.G4.MEASUR.TIME.WORK_OUT_DURATION', 'Gives the wrong a.m./p.m. when a time goes across noon.', '{"question":"A lesson starts at 11:30 a.m. and lasts 1 hour. When does it end?","wrong_answer":"12:30 a.m.","correct_answer":"12:30 p.m."}'::jsonb, 'Does not change a.m. at noon.', 'A duration across noon.', 'A.m. changes to p.m. at 12.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.TIME.DIGITAL_CLOCK.M_TIME_DIGITAL_BASE_10', 'MATH.G4.MEASUR.TIME.DIGITAL_CLOCK', 'Reads the digits after the colon as a decimal fraction of an hour.', '{"question":"A digital clock shows 7:45. How many minutes past 7 is that?","wrong_answer":"45 hundredths of an hour","correct_answer":"45 minutes"}'::jsonb, 'Treats the minutes as hundredths.', 'A digital reading.', 'The number after the colon is the minutes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.TIME.DIGITAL_CLOCK.M_TIME_DIGITAL_ANALOGUE_SWAP', 'MATH.G4.MEASUR.TIME.DIGITAL_CLOCK', 'Writes 3:45 as quarter past 3 because of 45.', '{"question":"What time is 3:45 on an analogue clock?","wrong_answer":"quarter past 3","correct_answer":"quarter to 4"}'::jsonb, 'Links 45 to a quarter without thinking about which.', 'A 45 minutes reading.', '45 minutes past the hour is 15 to the next hour.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.TIME.DIGITAL_CLOCK.M_TIME_24H_AS_AM', 'MATH.G4.MEASUR.TIME.DIGITAL_CLOCK', 'Reads 13:00 as 3:00 or reads the 24-hour clock as a.m.', '{"question":"What time is 15:00 on a 12-hour clock?","wrong_answer":"3:00 a.m.","correct_answer":"3:00 p.m."}'::jsonb, 'Does not know how to subtract 12.', 'A 24-hour time.', 'Subtract 12 from the hours in the afternoon.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.TIME.TELL_TIME_AM_PM.M_TIME_HOUR_FROM_NEXT_NUMBER', 'MATH.G4.MEASUR.TIME.TELL_TIME_AM_PM', 'Reads the hour from the number the hour hand is moving towards.', '{"question":"The hour hand is just before 5 and the minute hand points to 9. What time is it?","wrong_answer":"5:45","correct_answer":"4:45"}'::jsonb, 'Takes the nearest number to the hour hand, not the one it has passed.', 'The answer 5:45 as a wrong option, with a reason that names the idea.', 'The hour is the number the short hand has just passed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.TIME.ESTIMATE_TIME.M_TIME_PM_MEANS_EVENING', 'MATH.G4.MEASUR.TIME.ESTIMATE_TIME', 'Thinks p.m. starts in the evening, so an afternoon time is a.m.', '{"question":"Lunch is at 1 o''clock in the afternoon. Is that a.m. or p.m.?","wrong_answer":"a.m.","correct_answer":"p.m."}'::jsonb, 'Links p.m. with darkness, not with after noon.', 'The answer a.m. as a wrong option, with a reason that names the idea.', 'p.m. starts at 12 noon: everything after midday is p.m.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.TIME.ESTIMATE_TIME.M_TIME_SHADOW_POINTS_TO_SUN', 'MATH.G4.MEASUR.TIME.ESTIMATE_TIME', 'Thinks a shadow points towards the sun.', '{"question":"In the morning the sun is in the east. Which way does the shadow of a flagpole point?","wrong_answer":"east","correct_answer":"west"}'::jsonb, 'Does not picture the sun behind the object.', 'The answer east as a wrong option, with a reason that names the idea.', 'Stand with your back to the sun in the morning: your shadow is in front of you, to the west.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.TIME.CONVERT_HOURS_MINUTES.M_TIME_HALF_HOUR_50', 'MATH.G4.MEASUR.TIME.CONVERT_HOURS_MINUTES', 'Says half an hour is 50 minutes.', '{"question":"How many minutes are there in half an hour?","wrong_answer":"50","correct_answer":"30"}'::jsonb, 'Halves 100 instead of 60.', 'The answer 50 as a wrong option, with a reason that names the idea.', 'Half of 60 is 30: the minute hand goes half way round.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.TIME.CONVERT_DAYS_WEEKS.M_TIME_WEEKS_ADDS_7', 'MATH.G4.MEASUR.TIME.CONVERT_DAYS_WEEKS', 'Adds 7 instead of multiplying by 7 when changing weeks to days.', '{"question":"How many days are there in 3 weeks?","wrong_answer":"10","correct_answer":"21"}'::jsonb, 'Knows 7 is involved but adds it once.', 'The answer 10 as a wrong option, with a reason that names the idea.', 'Each week has 7 days: 7 + 7 + 7, or 3 x 7.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.TIME.CONVERT_DAYS_WEEKS.M_TIME_HOURS_REMAINDER_KEPT', 'MATH.G4.MEASUR.TIME.CONVERT_DAYS_WEEKS', 'Takes out one day but leaves all the hours in the hours part.', '{"question":"Change 30 hours to days and hours.","wrong_answer":"1 day 30 hours","correct_answer":"1 day 6 hours"}'::jsonb, 'Writes the day and copies the hours.', 'The answer 1 day 30 hours as a wrong option, with a reason that names the idea.', 'Take 24 hours out for the day: 30 - 24 = 6 hours left.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.TIME.RECORD_DURATION.M_TIME_DURATION_COUNTS_NUMBERS', 'MATH.G4.MEASUR.TIME.RECORD_DURATION', 'Counts the numbers on the clock from start to end, so 9 to 11 is 3 hours.', '{"question":"From 9 o''clock to 11 o''clock is how long?","wrong_answer":"3 hours","correct_answer":"2 hours"}'::jsonb, 'Counts the hour marks instead of the jumps between them.', 'The answer 3 hours as a wrong option, with a reason that names the idea.', 'Count the jumps: 9 to 10 is one hour, 10 to 11 is another.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.TIME.RECORD_DURATION.M_TIME_DURATION_ACROSS_HOUR', 'MATH.G4.MEASUR.TIME.RECORD_DURATION', 'Takes the hours from the hours and the minutes from the minutes when the time passes an hour.', '{"question":"From 9:40 to 10:10 is how long?","wrong_answer":"1 hour 30 minutes","correct_answer":"30 minutes"}'::jsonb, 'Subtracts each part on its own.', 'The answer 1 hour 30 minutes as a wrong option, with a reason that names the idea.', 'Count on: 9:40 to 10:00 is 20 minutes, then 10 more.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.TIME.WORK_OUT_DURATION.M_TIME_HOURS_ADDED_AS_MINUTES', 'MATH.G4.MEASUR.TIME.WORK_OUT_DURATION', 'Adds the hours of a duration to the minutes.', '{"question":"A trip starts at 7:15 and takes 2 hours 20 minutes. When does it end?","wrong_answer":"7:37","correct_answer":"9:35"}'::jsonb, 'Adds 2 and 20 as minutes.', 'The answer 7:37 as a wrong option, with a reason that names the idea.', 'Add the hours to the hours and the minutes to the minutes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.MEASUR.TIME.DIGITAL_CLOCK.M_TIME_DIGITAL_MINUTES_UNDER_10', 'MATH.G4.MEASUR.TIME.DIGITAL_CLOCK', 'Writes a time a few minutes past the hour without the 0, as 3:7 or 3:70.', '{"question":"Write 7 minutes past 3 as on a digital clock.","wrong_answer":"3:70","correct_answer":"3:07"}'::jsonb, 'Does not know the minutes always take two digits.', 'The answer 3:70 as a wrong option, with a reason that names the idea.', 'Minutes have two places, like tens and ones: 7 minutes is 07.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
