INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.GEOMET.POSITION_AND_DIRECTION.CLOCKWISE_ANTI.M_TURN_VIEWED_FROM_BEHIND', 'MATH.G4.GEOMET.POSITION_AND_DIRECTION.CLOCKWISE_ANTI', 'Reverses the direction when the turn is seen from behind or below.', '{"question":"A tap is turned the way a clock turns when seen from above. Seen from below which way is it?","wrong_answer":"the same","correct_answer":"opposite"}'::jsonb, 'Does not see that the direction depends on the viewpoint.', 'A turn viewed from the other side.', 'Turn a paper clock over.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.GEOMET.POSITION_AND_DIRECTION.CLOCKWISE_ANTI.M_TURN_ANTI_MEANING', 'MATH.G4.GEOMET.POSITION_AND_DIRECTION.CLOCKWISE_ANTI', 'Does not know that anti-clockwise is the opposite of clockwise.', '{"question":"Which turn is the opposite of clockwise?","wrong_answer":"quarter turn","correct_answer":"anticlockwise"}'::jsonb, 'Does not know the word.', 'A word choice.', 'Anti means against.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.GEOMET.POSITION_AND_DIRECTION.TURN_FRACTIONS.M_TURN_QUARTER_AS_HALF', 'MATH.G4.GEOMET.POSITION_AND_DIRECTION.TURN_FRACTIONS', 'Thinks a quarter turn is half way round.', '{"question":"How much of a full turn is a quarter turn?","wrong_answer":"half","correct_answer":"one quarter"}'::jsonb, 'Mixes up the fractions.', 'A fraction of a turn.', 'Four quarter turns make a full turn.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.GEOMET.POSITION_AND_DIRECTION.TURN_FRACTIONS.M_TURN_FACING_WRONG', 'MATH.G4.GEOMET.POSITION_AND_DIRECTION.TURN_FRACTIONS', 'Names the wrong direction after a quarter turn.', '{"question":"You face north and turn a quarter turn clockwise. Which way are you facing?","wrong_answer":"west","correct_answer":"east"}'::jsonb, 'Mixes left and right.', 'A direction change after a turn.', 'Clockwise from north is east.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.GEOMET.POSITION_AND_DIRECTION.TURN_FRACTIONS.M_TURN_FULL_AS_NO_TURN', 'MATH.G4.GEOMET.POSITION_AND_DIRECTION.TURN_FRACTIONS', 'Says a full turn does not change anything and so is not a turn.', '{"question":"You face east and make a full turn. Which way are you facing?","wrong_answer":"a full turn is not a turn","correct_answer":"east"}'::jsonb, 'Thinks nothing changed.', 'A full turn question.', 'You came back to where you started.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.GEOMET.POSITION_AND_DIRECTION.TURN_FRACTIONS.M_TURN_HALF_AS_RIGHT', 'MATH.G4.GEOMET.POSITION_AND_DIRECTION.TURN_FRACTIONS', 'Says a half turn faces the right.', '{"question":"You face north and make a half turn. Which way do you face?","wrong_answer":"east","correct_answer":"south"}'::jsonb, 'Mixes right with half.', 'A half turn.', 'A half turn faces you the opposite way.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.GEOMET.POSITION_AND_DIRECTION.CLOCKWISE_ANTI.M_TURN_OPENING_LID_CLOCKWISE', 'MATH.G4.GEOMET.POSITION_AND_DIRECTION.CLOCKWISE_ANTI', 'Thinks a bottle top or tap opens with a clockwise turn.', '{"question":"Which way do you turn a bottle top to open it?","wrong_answer":"clockwise","correct_answer":"anticlockwise"}'::jsonb, 'Has not linked the everyday action to the words.', 'The answer clockwise as a wrong option, with a reason that names the idea.', 'Open a bottle in class while a clock is held beside it and compare the directions.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.GEOMET.ANGLES.ANGLE_AT_POINT.M_ANGLE_ARM_LENGTH', 'MATH.G4.GEOMET.ANGLES.ANGLE_AT_POINT', 'Thinks an angle with longer arms is bigger.', '{"question":"Two angles have the same opening. One has longer arms. Which is bigger?","wrong_answer":"the one with longer arms","correct_answer":"they are the same size"}'::jsonb, 'Compares the length of the lines.', 'Two angles with different arm lengths.', 'Trace the angles onto paper and put one over the other.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.GEOMET.ANGLES.ANGLE_AT_POINT.M_ANGLE_IS_THE_LINE', 'MATH.G4.GEOMET.ANGLES.ANGLE_AT_POINT', 'Says the angle is the line, not the opening.', '{"question":"What is an angle?","wrong_answer":"a straight line","correct_answer":"the opening between two lines at a point"}'::jsonb, 'Does not see the space.', 'A definition choice.', 'Open two sticks joined at one end.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.GEOMET.ANGLES.ANGLE_AT_POINT.M_ANGLE_COUNT_SIDES', 'MATH.G4.GEOMET.ANGLES.ANGLE_AT_POINT', 'Counts the sides and not the corners when asked for the angles.', '{"question":"How many angles has a triangle?","wrong_answer":"6","correct_answer":"3"}'::jsonb, 'Counts every line twice or mixes with sides.', 'A shape question.', 'Count each corner once.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.GEOMET.ANGLES.ANGLES_IN_OBJECTS.M_ANGLE_CURVED_HAS_ANGLE', 'MATH.G4.GEOMET.ANGLES.ANGLES_IN_OBJECTS', 'Says a circle has angles at its edge.', '{"question":"How many corners has a circle?","wrong_answer":"4","correct_answer":"0"}'::jsonb, 'Treats a curved edge as having corners.', 'A shape with no corners.', 'Run a finger round the circle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.GEOMET.ANGLES.ANGLES_IN_OBJECTS.M_ANGLE_RECTANGLE_ANGLES', 'MATH.G4.GEOMET.ANGLES.ANGLES_IN_OBJECTS', 'Says a rectangle has two angles (its long sides) or six.', '{"question":"How many angles has a rectangle?","wrong_answer":"2","correct_answer":"4"}'::jsonb, 'Counts the lengths.', 'A shape question.', 'Count the corners one by one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
