INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.GEOMET.ANGLES.TURN_TO_ANGLE.M_TURN_QUARTER_AS_STRAIGHT', 'MATH.G4.GEOMET.ANGLES.TURN_TO_ANGLE', 'Says a quarter turn makes a straight line.', '{"question":"What angle does a quarter turn make?","wrong_answer":"a straight line","correct_answer":"a right angle"}'::jsonb, 'Mixes quarter with half.', 'A quarter turn question.', 'Fold a paper twice.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.GEOMET.ANGLES.TURN_TO_ANGLE.M_TURN_ANGLE_SMALLER_TURN', 'MATH.G4.GEOMET.ANGLES.TURN_TO_ANGLE', 'Says a bigger turn gives a smaller angle.', '{"question":"Which turn makes the bigger angle, a quarter turn or a half turn?","wrong_answer":"quarter turn","correct_answer":"half turn"}'::jsonb, 'Reads quarter as larger than half.', 'A comparison.', 'Turn your arm: the further you turn, the bigger the angle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
