INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.GEOMET.PLANE_FIGURES.IDENTIFY_FIGURES.M_SHAPE_ORIENTATION', 'MATH.G4.GEOMET.PLANE_FIGURES.IDENTIFY_FIGURES', 'Calls a square turned on its corner a diamond or a different shape.', '{"question":"A square is turned so it stands on a corner. What shape is it?","wrong_answer":"diamond","correct_answer":"square"}'::jsonb, 'Judges shape by how it sits on the page.', 'A turned square.', 'Count the sides and check they are equal.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
