INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.GEOMET.PLANE_FIGURES.LINES_SYMMETRY.M_SYM_ANY_LINE', 'MATH.G4.GEOMET.PLANE_FIGURES.LINES_SYMMETRY', 'Says any line through a shape is a line of symmetry.', '{"question":"Is a line cutting a rectangle into two parts a line of symmetry?","wrong_answer":"yes, it makes two parts","correct_answer":"only if the halves fit exactly"}'::jsonb, 'Thinks any cut makes two matching halves.', 'A diagonal fold.', 'Fold along it and see if the edges meet.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
