INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.GEOMET.PLANE_FIGURES.SHAPE_PATTERNS.M_SPAT_COLOUR_ONLY', 'MATH.G4.GEOMET.PLANE_FIGURES.SHAPE_PATTERNS', 'Looks at the colour only and ignores the shape.', '{"question":"Red square, blue triangle, red square, ?","wrong_answer":"red triangle","correct_answer":"blue triangle"}'::jsonb, 'Matches the colour pattern but not the shape.', 'A pattern with both colour and shape.', 'Say the colour and the shape together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.GEOMET.PLANE_FIGURES.FIGURE_PROPERTIES.M_PROP_RECT_ALL_SIDES_EQUAL', 'MATH.G4.GEOMET.PLANE_FIGURES.FIGURE_PROPERTIES', 'Says the four sides of a rectangle are all equal.', '{"question":"Which sides of a rectangle are equal?","wrong_answer":"all four","correct_answer":"opposite sides"}'::jsonb, 'Transfers from the square.', 'A rectangle.', 'Measure the sides of a rectangle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.GEOMET.PLANE_FIGURES.FIGURE_PROPERTIES.M_PROP_SQUARE_NOT_RECT', 'MATH.G4.GEOMET.PLANE_FIGURES.FIGURE_PROPERTIES', 'Says a square is not a rectangle.', '{"question":"Is a square a rectangle?","wrong_answer":"No","correct_answer":"Yes, it is a rectangle with equal sides"}'::jsonb, 'Learns the shapes as different groups.', 'A property question.', 'A rectangle has four square corners and so does a square.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.GEOMET.PLANE_FIGURES.FIGURE_PROPERTIES.M_PROP_COUNT_SIDES_CORNERS', 'MATH.G4.GEOMET.PLANE_FIGURES.FIGURE_PROPERTIES', 'Gives the wrong number of sides or corners for a triangle.', '{"question":"How many corners has a triangle?","wrong_answer":"4","correct_answer":"3"}'::jsonb, 'Mixes up with the square.', 'A shape property.', 'Trace the sides and count.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.GEOMET.PLANE_FIGURES.IDENTIFY_FIGURES.M_SHAPE_SOLID_FOR_FACE', 'MATH.G4.GEOMET.PLANE_FIGURES.IDENTIFY_FIGURES', 'Names the solid object instead of the flat shape of its face.', '{"question":"What shape is the top of a round tin seen from above?","wrong_answer":"cylinder","correct_answer":"circle"}'::jsonb, 'Names the object, not the shape traced from it.', 'The answer cylinder as a wrong option, with a reason that names the idea.', 'Trace round the top of the tin on paper and name the flat shape.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.GEOMET.PLANE_FIGURES.DRAW_FIGURES.M_DRAW_OVAL_POINTED', 'MATH.G4.GEOMET.PLANE_FIGURES.DRAW_FIGURES', 'Draws an oval with pointed ends, like a leaf.', '{"question":"A child draws an oval with two sharp points. Is it an oval?","wrong_answer":"yes","correct_answer":"no: an oval is a smooth curve with no corners"}'::jsonb, 'Draws two curves that meet in points.', 'The answer yes as a wrong option, with a reason that names the idea.', 'Trace round an egg: the line never makes a corner.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.GEOMET.PLANE_FIGURES.DRAW_FIGURES.M_DRAW_CORNERS_ROUNDED', 'MATH.G4.GEOMET.PLANE_FIGURES.DRAW_FIGURES', 'Rounds the corners of a rectangle or square.', '{"question":"A rectangle is drawn with curved corners. Is it a rectangle?","wrong_answer":"yes","correct_answer":"no: a rectangle has four square corners"}'::jsonb, 'Draws quickly without a ruler.', 'The answer yes as a wrong option, with a reason that names the idea.', 'Use a ruler for each side and check each corner with a book corner.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.GEOMET.PLANE_FIGURES.LINES_SYMMETRY.M_SYM_SQUARE_TWO_ONLY', 'MATH.G4.GEOMET.PLANE_FIGURES.LINES_SYMMETRY', 'Finds only the two lines across a square, missing the two diagonals.', '{"question":"How many lines of symmetry has a square?","wrong_answer":"2","correct_answer":"4"}'::jsonb, 'Folds only across, not corner to corner.', 'The answer 2 as a wrong option, with a reason that names the idea.', 'Fold a paper square corner to corner too: the halves fit.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.GEOMET.PLANE_FIGURES.SHAPE_PATTERNS.M_SPAT_SIZE_IGNORED', 'MATH.G4.GEOMET.PLANE_FIGURES.SHAPE_PATTERNS', 'Ignores the size of the shapes when continuing a pattern.', '{"question":"Big square, small square, big square, ?","wrong_answer":"big square","correct_answer":"small square"}'::jsonb, 'Looks at the kind of shape only.', 'The answer big square as a wrong option, with a reason that names the idea.', 'Say the pattern aloud with the size: big, small, big, small.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.GEOMET.PLANE_FIGURES.SHAPE_PATTERNS.M_SPAT_TURN_IGNORED', 'MATH.G4.GEOMET.PLANE_FIGURES.SHAPE_PATTERNS', 'Ignores which way a shape points when continuing a pattern.', '{"question":"Triangle pointing up, triangle pointing down, triangle pointing up, ?","wrong_answer":"triangle pointing up","correct_answer":"triangle pointing down"}'::jsonb, 'Sees "triangle" and repeats it.', 'The answer triangle pointing up as a wrong option, with a reason that names the idea.', 'Point with your hand each time: up, down, up, down.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.GEOMET.PLANE_FIGURES.FIGURE_PROPERTIES.M_PROP_OVAL_LIKE_CIRCLE', 'MATH.G4.GEOMET.PLANE_FIGURES.FIGURE_PROPERTIES', 'Thinks every point on the edge of an oval is the same distance from the middle, as in a circle.', '{"question":"Is every point on the edge of an oval the same distance from the middle?","wrong_answer":"yes","correct_answer":"no: only a circle is"}'::jsonb, 'Treats an oval as a stretched circle with the same property.', 'The answer yes as a wrong option, with a reason that names the idea.', 'Measure from the middle of an oval cut-out to its edge at the end and at the side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.DATA_H.DATA.COLLECT_DATA.M_COLLECT_COUNTS_TWICE', 'MATH.G4.DATA_H.DATA.COLLECT_DATA', 'Counts the same learner twice when collecting data.', '{"question":"A child counts learners as they walk past. Why might the count be wrong?","wrong_answer":"the count is always right","correct_answer":"someone was counted twice"}'::jsonb, 'Does not mark each one counted.', 'A collection check in class.', 'Make one tally mark for each learner only.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.DATA_H.DATA.COLLECT_DATA.M_COLLECT_TOO_MANY_ITEMS', 'MATH.G4.DATA_H.DATA.COLLECT_DATA', 'Collects too many kinds of items to record in a small table.', '{"question":"The class collects data on at most 10 items. A child lists 15 kinds of fruit. What should she do?","wrong_answer":"record all 15","correct_answer":"choose at most 10"}'::jsonb, 'Does not keep to the number agreed.', 'A collection check in class.', 'Decide the items before collecting.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.DATA_H.DATA.DATA_MATERIALS.M_DATA_TALLY_ONES', 'MATH.G4.DATA_H.DATA.DATA_MATERIALS', 'Writes a tally in ones, with no groups of five.', '{"question":"How do you show 7 with tally marks?","wrong_answer":"IIIIIII","correct_answer":"IIII with a line across, then II"}'::jsonb, 'Does not know the groups of five.', 'A tally question.', 'Draw four lines and cross them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.DATA_H.DATA.DATA_MATERIALS.M_DATA_WRONG_TOOL', 'MATH.G4.DATA_H.DATA.DATA_MATERIALS', 'Chooses a calculator or a ruler to collect a count.', '{"question":"What can you use to record the number of learners in each class?","wrong_answer":"a ruler","correct_answer":"a table"}'::jsonb, 'Does not know the tools of data.', 'A choice of tools.', 'Name what you write on.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.DATA_H.DATA.TABLE_RECORD.M_TABLE_TALLY_COUNTS_BARS', 'MATH.G4.DATA_H.DATA.TABLE_RECORD', 'Counts the groups of five tally marks as five lines or counts a crossed bundle as 4.', '{"question":"A tally shows IIII crossed and II. How many?","wrong_answer":"6","correct_answer":"7"}'::jsonb, 'Does not count the crossing line.', 'A tally of five.', 'A crossed bundle is five.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.DATA_H.DATA.TABLE_RECORD.M_TABLE_ITEM_LEFT_OUT', 'MATH.G4.DATA_H.DATA.TABLE_RECORD', 'Leaves an item out of the table or writes it twice.', '{"question":"A table lists 3 kinds of fruit from a survey of 4 kinds. What is wrong?","wrong_answer":"nothing","correct_answer":"one kind is missing"}'::jsonb, 'Does not check against the data.', 'A table with a missing row.', 'Tick each item as you write it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.DATA_H.DATA.TABLE_RECORD.M_TABLE_HEADINGS_MISSING', 'MATH.G4.DATA_H.DATA.TABLE_RECORD', 'Writes numbers in a table with no headings.', '{"question":"Which table is complete?","wrong_answer":"one with only numbers","correct_answer":"one with headings and numbers"}'::jsonb, 'Does not see why headings matter.', 'A table with and one without headings.', 'A heading tells what the number counts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.DATA_H.DATA.INTERPRET_TABLE.M_TABLE_MOST_AS_LAST_ROW', 'MATH.G4.DATA_H.DATA.INTERPRET_TABLE', 'Gives the last row as the most.', '{"question":"A table shows mangoes 8, oranges 12, bananas 5. Which is most?","wrong_answer":"bananas","correct_answer":"oranges"}'::jsonb, 'Reads the list order as the size.', 'A table where the most is in the middle.', 'Compare the numbers, not the order.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.DATA_H.DATA.INTERPRET_TABLE.M_TABLE_ADDS_FOR_DIFFERENCE', 'MATH.G4.DATA_H.DATA.INTERPRET_TABLE', 'Adds when asked how many more.', '{"question":"Oranges 12 and mangoes 8. How many more oranges than mangoes?","wrong_answer":"20","correct_answer":"4"}'::jsonb, 'Reads more as join.', 'A how many more question.', 'Find the difference.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.DATA_H.DATA.INTERPRET_TABLE.M_TABLE_NAME_NOT_NUMBER', 'MATH.G4.DATA_H.DATA.INTERPRET_TABLE', 'Gives the name of the item when asked for the number.', '{"question":"How many learners like football? (Football 14)","wrong_answer":"football","correct_answer":"14"}'::jsonb, 'Does not read what is asked.', 'A number question.', 'Underline how many.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.DATA_H.DATA.DATA_MATERIALS.M_DATA_GATE_OF_SIX', 'MATH.G4.DATA_H.DATA.DATA_MATERIALS', 'Draws five strokes and then crosses them, so each tally gate counts 6.', '{"question":"How do you show 5 with tally marks?","wrong_answer":"five strokes and a line across them","correct_answer":"four strokes with the fifth across them"}'::jsonb, 'Does not know the crossing stroke is the fifth.', 'The answer five strokes and a line across them as a wrong option, with a reason that names the idea.', 'Count each stroke aloud as you draw it: one, two, three, four, and the fifth goes across.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.DATA_H.DATA.DATA_MATERIALS.M_DATA_NO_RECORD', 'MATH.G4.DATA_H.DATA.DATA_MATERIALS', 'Thinks a count can be kept in the head while counting many things.', '{"question":"Why make tally marks while counting the cars that pass the school gate?","wrong_answer":"no need, I will remember","correct_answer":"so the count is not lost or forgotten"}'::jsonb, 'Has only counted small numbers before.', 'The answer no need, I will remember as a wrong option, with a reason that names the idea.', 'Try counting cars for five minutes without marks, then with marks, and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.DATA_H.DATA.DATA_MATERIALS.M_DATA_LIST_AS_TABLE', 'MATH.G4.DATA_H.DATA.DATA_MATERIALS', 'Thinks a list of answers written one by one is the same as a table.', '{"question":"Learners write their favourite fruits one by one: mango, orange, mango, banana. Is that a table?","wrong_answer":"yes","correct_answer":"no: a table puts each fruit once with its count"}'::jsonb, 'Has not seen how a table groups the data.', 'The answer yes as a wrong option, with a reason that names the idea.', 'Turn the list into a table: one row for each fruit and a count beside it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.DATA_H.DATA.COLLECT_DATA.M_COLLECT_ONLY_FRIENDS', 'MATH.G4.DATA_H.DATA.COLLECT_DATA', 'Asks only some learners and says the answer is for the whole class.', '{"question":"To find the class''s favourite fruit, Amina asks her 4 friends. Is that the class''s favourite?","wrong_answer":"yes","correct_answer":"no: she must ask everyone in the class"}'::jsonb, 'Thinks a few answers stand for everyone.', 'The answer yes as a wrong option, with a reason that names the idea.', 'Ask: did everyone get a turn to answer?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.DATA_H.DATA.COLLECT_DATA.M_COLLECT_SOME_MISSED', 'MATH.G4.DATA_H.DATA.COLLECT_DATA', 'Leaves out some of the group when counting and does not notice.', '{"question":"A child counts only the learners in the front rows. Is the count of the class complete?","wrong_answer":"yes","correct_answer":"no: the learners at the back were missed"}'::jsonb, 'Counts what is easy to see.', 'The answer yes as a wrong option, with a reason that names the idea.', 'Tick each name on the class list as you count.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.DATA_H.DATA.TABLE_RECORD.M_TABLE_GATES_AS_NUMBER', 'MATH.G4.DATA_H.DATA.TABLE_RECORD', 'Writes the number of tally gates as the total.', '{"question":"A row shows two tally gates and III. What number goes in the total column?","wrong_answer":"2","correct_answer":"13"}'::jsonb, 'Counts the bundles, not the marks.', 'The answer 2 as a wrong option, with a reason that names the idea.', 'Each gate is 5: count 5, 10, then 11, 12, 13.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G4.DATA_H.DATA.INTERPRET_TABLE.M_TABLE_TOTAL_MISSES_ROW', 'MATH.G4.DATA_H.DATA.INTERPRET_TABLE', 'Adds only some of the rows when asked for the total.', '{"question":"Mangoes 8, oranges 12, bananas 5. How many fruits in all?","wrong_answer":"20","correct_answer":"25"}'::jsonb, 'Stops before the last row.', 'The answer 20 as a wrong option, with a reason that names the idea.', 'Tick each row as you add it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
